  .theme-swatch{box-shadow:0 0 16px -10px currentColor;}

  /* Settings / Encyclopedia */
  .overlay{
    background:color-mix(in srgb,var(--bg) 72%,transparent);
    backdrop-filter:blur(11px) saturate(.95);
  }
  .settings-modal,.modal{
    border-color:var(--soft-line);
    background:linear-gradient(160deg,color-mix(in srgb,var(--bg-elev) 97%,transparent),color-mix(in srgb,var(--bg-elev-2) 94%,transparent));
