  }
  .settings-head{
    padding-top:calc(12px + var(--safe-top));
    background:color-mix(in srgb,var(--bg-elev) 75%,transparent);backdrop-filter:blur(12px);
  }
  .settings-scroll{padding-bottom:calc(16px + var(--safe-bottom));}
  .settings-row,.ency-card{
    border-color:var(--soft-line);
    background:linear-gradient(150deg,color-mix(in srgb,var(--bg-elev-2) 88%,transparent),color-mix(in srgb,var(--bg-elev) 92%,transparent));
    box-shadow:var(--inner-highlight);
  }
  .settings-row:active{transform:scale(.992);}
  .ency-status.on{background:color-mix(in srgb,var(--good) 9%,var(--bg-elev));border:1px solid color-mix(in srgb,var(--good) 22%,var(--line));}
  .save-backup-textarea{border-color:var(--soft-line);box-shadow:inset 0 2px 12px rgba(0,0,0,.04);}

  /* compact-screen safeguards */
  @media (max-width:380px){
    .hud{gap:4px;padding-left:9px;padding-right:9px;}
    .chip{padding:4px 6px;}
    .chip .lbl{font-size:.5rem;}
    .chip .val{font-size:.69rem;}
    main{padding-left:9px;padding-right:9px;}
    .stage{padding-left:10px!important;padding-right:10px!important;}
    .party-col{width:56px;}
    .enemy-stage{width:142px;height:142px;}
    .enemy-glyph{width:91px;height:91px;}
    .enemy-glyph.boss{width:104px;height:104px;}
    .node-card{gap:8px;padding:11px;}
    .buy-btn{min-width:72px!important;padding-left:7px;padding-right:7px;}
    .ascend-breakdown{gap:7px;}
    .ab-col{padding:8px 9px;}
  }
  @media (prefers-reduced-motion:reduce){
    *,*::before,*::after{scroll-behavior:auto!important;animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important;}
  }


  /* Wisp information hierarchy */
  .hero-chip{border-left:2px solid color-mix(in srgb,var(--wisp-color,var(--line)) 46%,var(--line));}
  .hero-stats{
    display:flex;align-items:center;gap:5px;flex-wrap:wrap;
    background:transparent;border:none;padding:0;margin:8px 0 7px;
  }
  .hero-stat-pill,.rarity-badge{
    display:inline-flex;align-items:center;min-height:24px;padding:3px 7px;border-radius:999px;
    font-size:.61rem;font-weight:850;line-height:1;
    background:color-mix(in srgb,var(--bg-elev) 75%,transparent);
    border:1px solid var(--soft-line);
  }
  .rarity-badge{
    color:var(--badge-color);border-color:color-mix(in srgb,var(--badge-color) 35%,var(--line));
    background:color-mix(in srgb,var(--badge-color) 7%,var(--bg-elev));
    box-shadow:0 0 14px -11px var(--badge-color);
  }
  .hero-stats .node-queue-toggle{margin-left:auto;}
  .hero-ability{
    display:grid;grid-template-columns:auto 1fr;column-gap:7px;row-gap:2px;align-items:center;
  }
  .ability-label{
    grid-row:1 / span 2;align-self:stretch;display:flex;align-items:center;
    font-size:.55rem;font-weight:900;letter-spacing:.08em;text-transform:uppercase;
    color:var(--wisp-color,var(--prism));
    border-right:1px solid color-mix(in srgb,var(--wisp-color,var(--prism)) 22%,var(--line));
    padding-right:7px;
  }
  .hero-ability strong{font-size:.72rem;}
  .ability-desc{font-size:.65rem;color:var(--ink-dim);line-height:1.35;}
  .hero-actions .mini-btn:first-child:not(:disabled){
    border-color:color-mix(in srgb,var(--lumen) 28%,var(--line));
  }
  .rarity-btn:not(:disabled){
    border-color:color-mix(in srgb,var(--prism) 30%,var(--line));
    background:color-mix(in srgb,var(--prism) 4%,var(--bg-elev));
  }

  /* clearer locked state */
  .hero-card.locked{
    min-height:68px;filter:saturate(.35);
    background:linear-gradient(135deg,color-mix(in srgb,var(--bg-elev-2) 85%,transparent),color-mix(in srgb,var(--bg) 88%,transparent));
  }
  .hero-card.locked::before{
    background:repeating-linear-gradient(180deg,var(--line) 0 4px,transparent 4px 8px);
  }

  /* polished actionable states */
  button:not(:disabled){-webkit-tap-highlight-color:transparent;}
  .buy-btn:not(:disabled),.mini-btn:not(:disabled),.shop-card button:not(:disabled),.quest-claim-btn:not(:disabled){
    cursor:pointer;
  }
  .buy-btn:not(:disabled){
    border-color:color-mix(in srgb,var(--lumen) 18%,var(--line));
  }
  .quest-claim-btn:not(:disabled){
    box-shadow:0 7px 18px -14px var(--good),var(--inner-highlight);
  }


  /* Final mobile ergonomics / resilience */
  body,.shell{min-height:100dvh;}
  button{touch-action:manipulation;}
  .settings-btn,.settings-icon-btn{min-width:40px;min-height:40px;}
  nav.tabbar button{min-height:52px;}
  .active-toggle,.node-queue-toggle,.quest-claim-btn{min-height:32px;}
  .buy-btn,.mini-btn,.speed-btn,.shop-card button,.save-backup-actions button,.big-btn,.primary-btn{min-height:44px;}
  .settings-row{min-height:56px;}
  .settings-overlay{
    padding:
      max(10px,var(--safe-top))
      max(10px,env(safe-area-inset-right))
      max(10px,var(--safe-bottom))
      max(10px,env(safe-area-inset-left));
  }
  .settings-modal{height:min(92dvh,760px);}
  .settings-scroll{-webkit-overflow-scrolling:touch;}
  .section-sub,.module-effect,.hero-ability,.settings-row-sub,.ency-desc,.shop-card .desc,.theme-info .desc,.boss-regen-tag{
    overflow-wrap:anywhere;
  }
  .hp-text,.chip-power,.quest-reward,.reward,.prism-preview{font-variant-numeric:tabular-nums;}
  .tab-panel{contain:layout style;}
  .enemy-stage,.hero-chip,.hero-card{will-change:auto;}
  @media (max-height:650px){
    .hud{padding-top:calc(7px + var(--safe-top));padding-bottom:6px;}
    nav.tabbar button{min-height:45px;padding-top:6px;padding-bottom:5px;}
    main{padding-top:10px;}
    .enemy-stage{width:136px;height:136px;}
    .enemy-glyph{width:88px;height:88px;}
    .enemy-glyph.boss{width:100px;height:100px;}
    .stage{gap:7px!important;}
  }


  /* Fixed mobile navigation + bounded app viewport */
  html,body{
    width:100%;
    height:100%;
    overscroll-behavior:none;
  }
  body{
    min-height:100dvh;
    overflow:hidden;
  }
  .shell{
    width:100%;
    height:100dvh;
    min-height:100dvh;
    overflow:hidden;
  }
  .topbar{
    position:relative;
    top:auto;
    z-index:12;
    flex:none;
  }
  main{
    min-height:0;
    overflow-y:auto;
    overflow-x:hidden;
    overscroll-behavior-y:contain;
    -webkit-overflow-scrolling:touch;
    scrollbar-width:none;
    padding-bottom:16px;
    margin-bottom:calc(var(--nav-height) + var(--safe-bottom));
  }
  main::-webkit-scrollbar{display:none;}
  /* Push is a single-screen combat view: never allow vertical drift/scroll. */
  main.rift-scroll-locked{
    overflow-y:hidden;
    overscroll-behavior-y:none;
    -webkit-overflow-scrolling:auto;
  }
  /* The Rift is a fixed combat viewport. Block vertical touch panning at the source. */
  #tab-battle{
    touch-action:pan-x;
    overscroll-behavior:none;
  }

  nav.tabbar{
    position:fixed;
    z-index:14;
    left:50%;
    bottom:0;
    transform:translateX(-50%);
    width:min(500px,100%);
    padding-bottom:var(--safe-bottom);
    border-top:1px solid var(--soft-line,var(--line));
    border-bottom:none;
    box-shadow:0 -12px 34px -28px rgba(0,0,0,.72);
  }
  nav.tabbar::before{
    content:'';
    position:absolute;
    inset:0;
    z-index:-1;
    background:color-mix(in srgb,var(--bg-elev) 94%,transparent);
    backdrop-filter:blur(18px) saturate(1.18);
  }
  nav.tabbar button{
    min-height:54px;
    padding:8px 2px 8px;
  }

  /* Rift should feel like a single screen when its content fits */
  #tab-battle{
    min-height:min-content;
  }

  @media (max-height:650px){
    :root{--nav-height:48px;}
    main{padding-bottom:10px;}
    nav.tabbar button{min-height:48px;}
  }


  /* Retention: compact visible next goal */
  .rift-objective{
    --objective-progress:0%;
    position:relative;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:8px;
    min-height:42px;padding:7px 9px 9px;border-radius:11px;overflow:hidden;
    border:1px solid color-mix(in srgb,var(--zone-accent,var(--prism)) 20%,var(--line));
    background:linear-gradient(135deg,color-mix(in srgb,var(--zone-accent,var(--prism)) 7%,var(--bg-elev)),color-mix(in srgb,var(--bg-elev-2) 82%,transparent));
    box-shadow:var(--inner-highlight);
  }
  .objective-kind{
    padding:3px 6px;border-radius:999px;font-size:.49rem;line-height:1;font-weight:900;letter-spacing:.09em;
    color:var(--zone-accent,var(--lumen));border:1px solid color-mix(in srgb,var(--zone-accent,var(--lumen)) 30%,var(--line));
    background:color-mix(in srgb,var(--zone-accent,var(--lumen)) 7%,var(--bg-elev));
  }
  .objective-copy{min-width:0;display:flex;flex-direction:column;gap:1px;text-align:left;}
  .objective-copy strong{font-size:.68rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  .objective-copy small{font-size:.56rem;color:var(--ink-dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  .objective-arrow{font-size:1rem;color:var(--ink-dim);opacity:.6;}
  .objective-boss .objective-kind{color:var(--danger);border-color:color-mix(in srgb,var(--danger) 35%,var(--line));}
  .objective-ascend-ready .objective-kind{color:var(--prism);border-color:color-mix(in srgb,var(--prism) 42%,var(--line));}
  .objective-farm .objective-kind{color:var(--shard);border-color:color-mix(in srgb,var(--shard) 35%,var(--line));}


  /* Combat impact / milestone layer */
  .combat-vfx{
    --vfx-color:var(--lumen);
    position:absolute;left:50%;top:50%;z-index:7;pointer-events:none;
    width:16px;height:16px;border-radius:50%;transform:translate(-50%,-50%);
  }
  .vfx-tap{
    border:2px solid color-mix(in srgb,var(--vfx-color) 80%,#fff);
    box-shadow:0 0 12px var(--vfx-color);
    animation:vfxTap .38s ease-out forwards;
  }
  .vfx-ability{
    background:radial-gradient(circle,#fff 0 5%,color-mix(in srgb,var(--vfx-color) 78%,#fff) 7% 13%,transparent 15%);
    box-shadow:0 0 26px 8px color-mix(in srgb,var(--vfx-color) 38%,transparent);
    animation:vfxAbility .55s cubic-bezier(.2,.8,.2,1) forwards;
  }
  .vfx-support{
    border:2px solid color-mix(in srgb,var(--vfx-color) 70%,#fff);
    box-shadow:0 0 0 5px color-mix(in srgb,var(--vfx-color) 12%,transparent),0 0 30px var(--vfx-color);
    animation:vfxSupport .7s ease-out forwards;
  }
  .vfx-death,.vfx-luminous-death,.vfx-boss-death{
    width:28px;height:28px;
    background:radial-gradient(circle,#fff 0 7%,color-mix(in srgb,var(--vfx-color) 80%,#fff) 8% 20%,color-mix(in srgb,var(--vfx-color) 30%,transparent) 30%,transparent 68%);
    animation:vfxDeath .62s cubic-bezier(.16,.84,.32,1) forwards;
  }
  .vfx-luminous-death{box-shadow:0 0 35px 10px color-mix(in srgb,var(--mote) 42%,transparent);}
  .vfx-boss-death{animation-duration:.82s;box-shadow:0 0 50px 14px color-mix(in srgb,var(--sigil) 42%,transparent);}
  @keyframes vfxTap{0%{opacity:.9;transform:translate(-50%,-50%) scale(.35);}100%{opacity:0;transform:translate(-50%,-50%) scale(4.4);}}
  @keyframes vfxAbility{0%{opacity:0;transform:translate(-50%,-50%) scale(.25) rotate(0deg);}28%{opacity:1;}100%{opacity:0;transform:translate(-50%,-50%) scale(8) rotate(35deg);}}
  @keyframes vfxSupport{0%{opacity:0;transform:translate(-50%,-50%) scale(.5);}25%{opacity:1;}100%{opacity:0;transform:translate(-50%,-50%) scale(7);}}
  @keyframes vfxDeath{0%{opacity:1;transform:translate(-50%,-50%) scale(.35);}55%{opacity:.95;}100%{opacity:0;transform:translate(-50%,-50%) scale(9);}}

  #tab-battle .stage.impact-tap,
  #tab-battle .stage.impact-kill{animation:none;}
  #tab-battle .stage.impact-ability{animation:stageAbility .4s ease-out;}
  #tab-battle .stage.impact-support{animation:stageSupport .48s ease-out;}
  #tab-battle .stage.impact-boss{animation:stageBoss .5s ease-out;}
  #tab-battle .stage.impact-victory{animation:stageVictory .52s ease-out;}
  #tab-battle .stage.impact-milestone{animation:stageMilestone .48s ease-out;}
  @keyframes stageAbility{0%,100%{filter:none;}45%{filter:brightness(1.13) saturate(1.13);}}
  @keyframes stageSupport{0%,100%{box-shadow:var(--deep-shadow),var(--inner-highlight);}50%{box-shadow:0 0 30px -8px color-mix(in srgb,var(--good) 45%,transparent),var(--inner-highlight);}}
  @keyframes stageBoss{0%,100%{transform:none;}35%{transform:scale(.992);box-shadow:0 0 30px -8px color-mix(in srgb,var(--danger) 55%,transparent);}}
  @keyframes stageVictory{0%,100%{filter:none;}35%{filter:brightness(1.22) saturate(1.18);}}
  @keyframes stageMilestone{0%,100%{filter:none;}40%{filter:brightness(1.15);}}

  .rift-milestone{
    --milestone-accent:var(--prism);
    position:absolute;z-index:20;left:50%;top:46%;transform:translate(-50%,-50%);
    width:min(86%,310px);padding:10px 13px;border-radius:13px;text-align:center;
    background:linear-gradient(145deg,color-mix(in srgb,var(--bg-elev) 92%,transparent),color-mix(in srgb,var(--milestone-accent) 10%,var(--bg-elev)));
    border:1px solid color-mix(in srgb,var(--milestone-accent) 46%,var(--line));
    box-shadow:0 16px 45px -22px rgba(0,0,0,.72),0 0 30px -16px var(--milestone-accent),var(--inner-highlight);
    backdrop-filter:blur(12px) saturate(1.15);
    animation:milestoneIn .38s cubic-bezier(.18,.86,.3,1) both;
    pointer-events:none;
  }
  .rift-milestone::after{
    content:'';position:absolute;left:15%;right:15%;bottom:0;height:2px;
    background:linear-gradient(90deg,transparent,var(--milestone-accent),transparent);
    box-shadow:0 0 10px var(--milestone-accent);
  }
  .rift-milestone .milestone-kicker{
    display:block;font-size:.49rem;font-weight:900;letter-spacing:.15em;color:var(--milestone-accent);margin-bottom:3px;
  }
  .rift-milestone strong{display:block;font-family:'Cinzel',serif;font-size:.9rem;letter-spacing:.035em;}
  .rift-milestone small{display:block;font-size:.59rem;color:var(--ink-dim);margin-top:3px;}
  .rift-milestone.leaving{animation:milestoneOut .38s ease forwards;}
  @keyframes milestoneIn{from{opacity:0;transform:translate(-50%,-42%) scale(.92);filter:blur(3px);}to{opacity:1;transform:translate(-50%,-50%) scale(1);filter:none;}}
  @keyframes milestoneOut{to{opacity:0;transform:translate(-50%,-56%) scale(1.02);}}

  /* Resource feedback colors */
  .float-damage{color:#fff;text-shadow:0 0 10px color-mix(in srgb,var(--danger) 38%,transparent);}
  .float-lumen{color:var(--lumen);text-shadow:0 0 12px color-mix(in srgb,var(--lumen) 48%,transparent);}
  .float-mote{color:var(--mote);text-shadow:0 0 12px color-mix(in srgb,var(--mote) 55%,transparent);}
  .float-sigil{color:var(--sigil);font-size:.95rem;text-shadow:0 0 14px color-mix(in srgb,var(--sigil) 58%,transparent);}

  /* Six regions now have distinct atmosphere, not only accent color */
  #tab-battle .stage[data-zone-theme="0"]{
    background:
      radial-gradient(circle at 50% 24%,rgba(235,211,116,.12),transparent 34%),
      radial-gradient(circle at 18% 72%,rgba(126,103,226,.08),transparent 30%),
      linear-gradient(160deg,color-mix(in srgb,var(--bg-elev-2) 94%,#18132b),color-mix(in srgb,var(--bg-elev) 96%,#101525));
  }
  #tab-battle .stage[data-zone-theme="1"]{
    background:
      radial-gradient(circle at 26% 24%,rgba(230,111,72,.15),transparent 30%),
      radial-gradient(circle at 78% 76%,rgba(115,39,34,.12),transparent 35%),
      linear-gradient(165deg,color-mix(in srgb,var(--bg-elev-2) 90%,#2d1616),color-mix(in srgb,var(--bg-elev) 94%,#171019));
  }
  #tab-battle .stage[data-zone-theme="2"]{
    background:
      linear-gradient(118deg,transparent 0 36%,rgba(134,220,244,.055) 36.5% 38%,transparent 38.5% 66%,rgba(134,220,244,.04) 66.5% 68%,transparent 68.5%),
      radial-gradient(circle at 66% 22%,rgba(114,185,207,.15),transparent 32%),
      linear-gradient(160deg,color-mix(in srgb,var(--bg-elev-2) 92%,#132530),color-mix(in srgb,var(--bg-elev) 95%,#101820));
  }
  #tab-battle .stage[data-zone-theme="3"]{
    background:
      repeating-radial-gradient(ellipse at 50% 110%,transparent 0 28px,rgba(85,127,209,.035) 29px 31px),
      radial-gradient(circle at 50% 20%,rgba(75,118,198,.14),transparent 35%),
      linear-gradient(180deg,color-mix(in srgb,var(--bg-elev-2) 92%,#101d38),color-mix(in srgb,var(--bg-elev) 95%,#0b1326));
  }
  #tab-battle .stage[data-zone-theme="4"]{
    background:
      linear-gradient(90deg,transparent 11%,rgba(141,101,212,.035) 12% 14%,transparent 15% 42%,rgba(141,101,212,.045) 43% 45%,transparent 46% 84%,rgba(141,101,212,.035) 85% 87%,transparent 88%),
      radial-gradient(circle at 50% 28%,rgba(141,101,212,.18),transparent 34%),
      linear-gradient(160deg,color-mix(in srgb,var(--bg-elev-2) 91%,#211332),color-mix(in srgb,var(--bg-elev) 95%,#100d20));
  }
  #tab-battle .stage[data-zone-theme="5"]{
    background:
      radial-gradient(circle at 50% 18%,rgba(210,91,157,.12),transparent 28%),
      radial-gradient(circle at 16% 82%,rgba(91,59,154,.12),transparent 30%),
      radial-gradient(circle at 84% 72%,rgba(192,99,156,.09),transparent 32%),
      linear-gradient(165deg,color-mix(in srgb,var(--bg-elev-2) 90%,#211020),color-mix(in srgb,var(--bg-elev) 95%,#090a16));
  }
  #tab-battle .stage[data-zone-theme="2"] .enemy-glyph:not(.boss){clip-path:polygon(50% 0,88% 18%,100% 62%,67% 100%,25% 91%,0 52%,15% 14%);}
  #tab-battle .stage[data-zone-theme="4"] .enemy-glyph:not(.boss){clip-path:polygon(50% 0,83% 17%,100% 50%,82% 85%,50% 100%,18% 85%,0 50%,17% 17%);}
  #tab-battle .stage[data-zone-theme="5"] .enemy-glyph:not(.boss){clip-path:polygon(50% 0,64% 27%,94% 18%,79% 48%,100% 68%,67% 73%,50% 100%,34% 73%,0 68%,21% 48%,6% 18%,36% 27%);}


  /* Wisp desire / collection journey */
  .roster-journey{
    --roster-progress:0%;
    position:relative;overflow:hidden;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:9px;
    min-height:49px;margin-bottom:10px;padding:8px 10px 10px;border-radius:13px;
    border:1px solid color-mix(in srgb,var(--prism) 22%,var(--line));
    background:
      radial-gradient(circle at 92% 0%,color-mix(in srgb,var(--prism) 11%,transparent),transparent 38%),
      linear-gradient(145deg,color-mix(in srgb,var(--bg-elev-2) 91%,transparent),color-mix(in srgb,var(--bg-elev) 94%,transparent));
    box-shadow:var(--inner-highlight);
  }
  .roster-journey::after{
    content:'';position:absolute;left:0;bottom:0;width:var(--roster-progress);height:2px;
    background:linear-gradient(90deg,var(--prism),var(--mote));
    box-shadow:0 0 10px color-mix(in srgb,var(--prism) 45%,transparent);transition:width .3s ease;
  }
  .roster-count{
    display:grid;place-items:center;width:34px;height:34px;border-radius:10px;
    font-size:.64rem;font-weight:850;color:var(--prism);
    background:color-mix(in srgb,var(--prism) 8%,var(--bg-elev));
    border:1px solid color-mix(in srgb,var(--prism) 25%,var(--line));
  }
  .roster-copy{display:flex;flex-direction:column;gap:2px;min-width:0;}
  .roster-copy strong{font-size:.69rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  .roster-copy small{font-size:.57rem;color:var(--ink-dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  .roster-label{font-size:.47rem;font-weight:900;letter-spacing:.12em;color:var(--ink-dim);writing-mode:vertical-rl;transform:rotate(180deg);}

  .hero-card.wisp-reward-recruit{animation:wispRecruit .68s ease-out;}
  .hero-card.wisp-reward-rarity{animation:wispRarity .68s ease-out;}
  .hero-card.wisp-reward-ultimate{animation:wispUltimate .72s ease-out;}
  @keyframes wispRecruit{0%,100%{transform:none;}38%{transform:translateY(-2px) scale(1.012);box-shadow:0 0 30px -8px var(--wisp-color),var(--inner-highlight);}}
  @keyframes wispRarity{0%,100%{filter:none;}35%{filter:brightness(1.18) saturate(1.22);box-shadow:0 0 34px -9px var(--rarity-color),var(--inner-highlight);}}
  @keyframes wispUltimate{0%,100%{filter:none;transform:none;}35%{filter:brightness(1.25);transform:scale(1.012);box-shadow:0 0 38px -7px var(--sigil),var(--inner-highlight);}}

  /* Ascend is a major progression beat */
  .ascend-flash{
    position:fixed;z-index:900;left:50%;top:46%;transform:translate(-50%,-50%);
    width:min(84vw,340px);padding:17px 18px;text-align:center;border-radius:17px;pointer-events:none;
    background:
      radial-gradient(circle at 50% 0%,color-mix(in srgb,var(--prism) 24%,transparent),transparent 48%),
      color-mix(in srgb,var(--bg-elev) 94%,transparent);
    border:1px solid color-mix(in srgb,var(--prism) 48%,var(--line));
    box-shadow:0 24px 70px -28px rgba(0,0,0,.78),0 0 45px -14px var(--prism),var(--inner-highlight);
    backdrop-filter:blur(15px) saturate(1.2);
    animation:ascendFlashIn .48s cubic-bezier(.17,.86,.28,1) both;
  }
  .ascend-flash span{display:block;font-size:.52rem;font-weight:900;letter-spacing:.2em;color:var(--prism);margin-bottom:5px;}
  .ascend-flash strong{display:block;font-family:'Cinzel',serif;font-size:1.3rem;letter-spacing:.07em;text-shadow:0 0 18px color-mix(in srgb,var(--prism) 48%,transparent);}
  .ascend-flash small{display:block;margin-top:6px;font-size:.61rem;color:var(--ink-dim);}
  .ascend-flash.leaving{animation:ascendFlashOut .4s ease forwards;}
  @keyframes ascendFlashIn{from{opacity:0;transform:translate(-50%,-42%) scale(.86);filter:blur(5px);}to{opacity:1;transform:translate(-50%,-50%) scale(1);filter:none;}}
  @keyframes ascendFlashOut{to{opacity:0;transform:translate(-50%,-57%) scale(1.035);}}

  /* Only meaningful notification dots */
  nav.tabbar button.has-attention::before{
    content:'';position:absolute;top:6px;right:calc(50% - 18px);width:6px;height:6px;border-radius:50%;
    background:var(--mote);box-shadow:0 0 9px var(--mote);
    animation:navAttention 1.8s ease-in-out infinite;
  }
  nav.tabbar button[data-tab="ascend"].has-attention::before{background:var(--prism);box-shadow:0 0 9px var(--prism);}
  @keyframes navAttention{0%,100%{transform:scale(.8);opacity:.65;}50%{transform:scale(1.15);opacity:1;}}


  .rift-objective.actionable{cursor:pointer;transition:transform .15s ease,border-color .15s ease,filter .15s ease;}
  .rift-objective.actionable:active{transform:scale(.985);filter:brightness(1.08);}
  .rift-objective.actionable .objective-arrow{color:var(--zone-accent,var(--prism));opacity:.9;}
  .objective-wisp-ready .objective-kind{color:var(--good);border-color:color-mix(in srgb,var(--good) 38%,var(--line));}


  /* Slow ambient motion: high visual value, low update pressure */
  #tab-battle .stage::before{
    animation:zoneDrift 13s ease-in-out infinite alternate;
  }
  #tab-battle .stage::after{
    animation:zoneSparkle 7s ease-in-out infinite alternate;
  }
  @keyframes zoneDrift{
    0%{transform:translate3d(-1.2%,-.8%,0) rotate(-6deg) scale(1);}
    100%{transform:translate3d(1.4%,1%,0) rotate(-3deg) scale(1.035);}
  }
  @keyframes zoneSparkle{
    0%{opacity:.42;filter:brightness(.9);}
    100%{opacity:.72;filter:brightness(1.12);}
  }


  /* Rift art direction: moonlit ruins, faceted creatures, illuminated sigils. */
  .art-definitions{position:absolute;width:0;height:0;overflow:hidden;pointer-events:none;}
  .hud .brand{display:flex;align-items:center;gap:9px;letter-spacing:.12em;font-size:1rem;}
  @media(max-width:360px){.hud .brand{letter-spacing:.04em;}}
  .brand-sigil{width:30px;height:30px;object-fit:contain;flex:none;filter:drop-shadow(0 0 8px rgba(230,183,89,.32));}
  .hud .chip{border-radius:9px;}
  nav.tabbar .nav-art{width:23px;height:23px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;}
  nav.tabbar button.active{color:var(--lumen);background:linear-gradient(0deg,color-mix(in srgb,var(--lumen) 9%,transparent),transparent);}
  nav.tabbar button.active .nav-art{filter:drop-shadow(0 0 6px color-mix(in srgb,var(--lumen) 45%,transparent));}
  main.rift-scroll-locked{padding:9px 10px 10px;display:flex;flex-direction:column;}
  #tab-battle.active{height:100%;min-height:0;flex:1;}
  #tab-battle .stage{
    --land-light:#9ca7ee;--land-far:#19233b;--land-stone:#101b30;--land-edge:#384867;
    color:var(--ink);
    height:100%;min-height:0;padding:12px 12px 10px;gap:8px;
    background:radial-gradient(ellipse at 50% 38%,var(--land-far) 0, #11182d 55%,#0b1121 100%)!important;
    border-color:#36405b;border-radius:20px;box-shadow:inset 0 1px 0 #62708a44,0 10px 30px #0003;
  }
  #tab-battle .stage::before{display:none;}
  #tab-battle .stage::after{background:linear-gradient(90deg,transparent,var(--zone-accent),transparent);inset:0 18% auto;height:1px;opacity:.6;animation:none;}
  #tab-battle .stage[data-zone-theme="1"]{--land-light:#f3a874;--land-far:#392331;--land-stone:#241c2b;--land-edge:#705044;}
  #tab-battle .stage[data-zone-theme="2"]{--land-light:#8ff0ed;--land-far:#143849;--land-stone:#102735;--land-edge:#42747c;}
  #tab-battle .stage[data-zone-theme="3"]{--land-light:#74b5ff;--land-far:#152c50;--land-stone:#0e213a;--land-edge:#365c85;}
  #tab-battle .stage[data-zone-theme="4"]{--land-light:#c194ff;--land-far:#2a2047;--land-stone:#1d1834;--land-edge:#584879;}
  #tab-battle .stage[data-zone-theme="5"]{--land-light:#f29bd2;--land-far:#361e3c;--land-stone:#211729;--land-edge:#754463;}
  .stage .depth-label{font-family:'Cinzel',serif;font-size:1.08rem;letter-spacing:.08em;flex:none;}
  .stage .depth-label .region-label{font-family:'Manrope',sans-serif;font-size:.55rem;letter-spacing:.18em;margin-top:3px;}
  .stage .rift-mode-row{flex:none;background:#090f20a6;border-color:#3b44594d;border-radius:11px;}
  .stage .rift-mode-btn{min-height:34px;font-size:.7rem;letter-spacing:.1em;}
  .stage .rift-mode-btn.active{color:#ffe1a0;background:linear-gradient(110deg,#6d50372e,#c4a0652e);box-shadow:inset 0 0 0 1px #eac07955,inset 0 1px 0 #f9dea62b;}
  .stage .rift-mode-btn:disabled{color:var(--ink-dim);opacity:1;}
  .stage .rift-mode-note{display:none;}
  .stage .rift-objective{flex:none;z-index:2;background:#141d30;border-color:#3d4963;min-height:39px;padding:6px 9px 8px;}
  .stage .enemy-name{position:relative;z-index:2;font-size:.9rem;letter-spacing:.035em;flex:none;margin:2px 0 -6px;}
  .stage .luminous-tag{font-size:.55rem;padding:2px 7px;margin-top:4px;flex:none;color:#ffbcd4;}
  .stage .battle-row{position:relative;isolation:isolate;flex:1;min-height:0;display:flex;flex-direction:column-reverse;align-items:stretch;gap:7px;margin:0 -4px;}
  .rift-landscape{position:absolute;inset:-38px -8px -8px;z-index:-1;overflow:hidden;border-radius:12px;pointer-events:none;}
  .rift-landscape>svg{position:absolute;width:100%;height:100%;opacity:.95;}
  /* P2-06A: static, region-specific silhouettes; no added layout or animation. */
  .region-landmark{display:none;}
  [data-zone-theme="0"] .region-verge,[data-zone-theme="1"] .region-canopy,
  [data-zone-theme="2"] .region-glass,[data-zone-theme="3"] .region-observatory,
  [data-zone-theme="4"] .region-basilica,[data-zone-theme="5"] .region-crown{display:inline;}
  .zone-prop{display:none;}
  [data-zone-theme="0"] .zone-stars,[data-zone-theme="1"] .zone-roots,[data-zone-theme="2"] .zone-crystals,
  [data-zone-theme="3"] .zone-orbits,[data-zone-theme="4"] .zone-spires,[data-zone-theme="5"] .zone-crown{display:inline;}
  .rift-landscape::after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,#11182d 0,transparent 20%,transparent 68%,#0b1121 100%);}
  .stage .enemy-stage-wrap{width:100%;flex:1;min-height:0;gap:2px;}
  .stage .enemy-stage{width:100%;height:auto;flex:1;min-height:0;}
  .stage .enemy-stage::before{inset:8% 18%;filter:none;opacity:.4;}
  .stage .enemy-stage::after{width:clamp(100px,23vh,200px);height:clamp(100px,23vh,200px);max-height:calc(100% - 8px);border:1px solid #99b6ef22;box-shadow:0 0 40px #8eaeff0a,inset 0 0 30px #b0a8ff0a;animation:none;}
  #tab-battle .stage .enemy-glyph{
    --creature-color:#504c80;--creature-rim:#b4a5dc;--creature-eye:#d5edff;
    width:clamp(90px,22vh,190px);height:auto;aspect-ratio:1;max-height:calc(100% - 40px);
    background:none;box-shadow:none;border-radius:0;clip-path:none;flex:none;
    filter:drop-shadow(0 12px 7px #0008) drop-shadow(0 0 12px #a6adfa33);animation:creatureFloat 4s ease-in-out infinite;
  }
  .creature-art{display:block;width:100%;height:100%;overflow:visible;pointer-events:none;filter:drop-shadow(0 0 1px var(--creature-rim));}
  /* Faceted portraits retain their elemental materials; trait light follows the silhouette. */
  .enemy-glyph.boss .creature-art{filter:drop-shadow(0 0 1px var(--creature-rim)) drop-shadow(0 0 4px color-mix(in srgb,var(--creature-rim) 45%,transparent));}
  #tab-battle .enemy-glyph::before,#tab-battle .enemy-glyph::after{display:none;}
  .boss-regalia{display:none;position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none;fill:none;stroke-width:1.25;filter:drop-shadow(0 1px 1px #070d1f);}
  #tab-battle .stage .enemy-glyph.boss{width:clamp(100px,24vh,208px);}
  .enemy-glyph.boss .boss-regalia{display:block;}
  .boss-regalia .boss-crest{display:none;}
  .boss-regalia .boss-crest path{vector-effect:non-scaling-stroke;}
  .trait-regrowth .boss-crest-regrowth,.trait-fractured .boss-crest-fractured,
  .trait-guardian .boss-crest-guardian{display:inline;}

  /* Species palettes retain their own anatomy; Boss trait accents override below. */
