  .rift-bond-effect{flex:1 1 42%;min-width:0;padding:2px 5px;border:0;border-left:2px solid var(--bond-color);border-radius:3px;background:color-mix(in srgb,var(--bond-color) 7%,transparent);font-size:10px;line-height:12px;color:#d2d1e4;}
  .stage .enemy-stage::after{background:conic-gradient(from 0deg,transparent 0 15%,#b9b6ff33 16% 17%,transparent 18% 48%,#b9b6ff33 49% 50%,transparent 51% 82%,#b9b6ff33 83% 84%,transparent 85%);animation:riftOrbit 32s linear infinite;width:min(200px,65cqh,65cqw);height:min(200px,65cqh,65cqw);max-width:none;max-height:none;}
  .vfx-ability{background:repeating-conic-gradient(var(--vfx-color) 0deg 5deg,transparent 6deg 45deg);}
  @media(prefers-reduced-motion:reduce){.stage .enemy-stage::after{animation:none!important;}.rift-charge>span{transition:none;}}

  @media(max-height:680px){
    .shell:has(#tab-battle.active) .hud{gap:3px;padding:calc(1px + var(--safe-top)) 10px 1px;}
    .shell:has(#tab-battle.active) .hud .chip{height:20px;padding:1px 3px;}
    main.rift-scroll-locked{padding:2px 10px;}
    #tab-battle .stage{padding:3px 8px;gap:1px!important;}
    .rift-heading{display:grid;grid-template-columns:minmax(0,1fr) 160px;gap:4px;height:44px;}
    .stage .depth-label{font-size:14px;line-height:18px;text-align:left;}
    .stage .rift-heading .rift-mode-row{height:44px;min-height:44px;padding:0;}
    .stage .rift-mode-btn{font-size:12px;letter-spacing:0;padding:2px;}
    .farm-depth{display:block;margin:0;font:10px/12px 'IBM Plex Mono',monospace;}
    .stage .battle-row{gap:2px;}
    .stage .hp-wrap{height:24px;}
    .stage .hp-text{font-size:11px;line-height:14px;margin-top:2px;}
    #boss-combat{padding:1px 6px;}
    .boss-net-value{display:none;}
    #rift-party,.rift-wisp{height:54px;}
    .rift-wisp{grid-template-rows:24px 3px 13px 10px;gap:0;padding:1px 3px;}
    #rift-party .wisp-portrait{width:24px;height:24px;}
    .rift-wisp-power{font-size:10px;line-height:10px;}
    .stage .buff-indicator{padding:0 8px;line-height:14px;}
    .stage .stat-box{padding:2px 7px;}
    .rift-bond-effect{padding:2px 5px;}
  }

  /* One continuous scenic field extends through HP, Boss status and the Formation. */
  .stage .battle-row{overflow:visible;border-radius:0;}
  .stage .rift-landscape{inset:-30px -4px -14px;border-radius:0;}
  .stage .region-landmark{opacity:.24;}
  .stage .rift-architecture{opacity:1;}
  .stage .stat-row{position:relative;z-index:1;align-items:stretch;}
  .stage .stat-box{border-color:#35425a88;border-radius:11px;background:linear-gradient(140deg,#26304b77,#131b2c);}
  .stage .hp-bar-track{box-shadow:none;}
  .stage .combat-vfx{z-index:1;}
  .combat-vfx.wisp-cast{width:84px;height:84px;max-width:70%;border-radius:50%;background:none;box-shadow:none;animation:wispCast .8s ease-out forwards;}
  .wisp-cast::before,.wisp-cast::after{content:'';position:absolute;inset:0;border-radius:inherit;pointer-events:none;}
  .cast-ember::before{background:repeating-conic-gradient(from 15deg,#ffd88a 0 4deg,var(--vfx-color) 5deg 10deg,transparent 11deg 45deg);}
  .cast-ember::after{inset:22%;background:radial-gradient(circle,#fff2c7,var(--vfx-color) 30%,transparent 70%);box-shadow:0 0 22px #ff912b66;}
  .cast-void::before{border:5px double #c5adff;box-shadow:inset 0 0 20px #955eff88,0 0 18px #955eff66;transform:rotateX(35deg);}
  .cast-void::after{inset:25%;background:#100f27;box-shadow:0 0 18px 5px var(--vfx-color);}
  .combat-vfx.cast-void{animation:wispVortex .85s ease-out forwards;}
  .cast-tide::before{border:3px solid #9beaff;box-shadow:0 0 0 10px #5abfd244,0 0 0 21px #5abfd21a;}
  .cast-tide::after{inset:28%;border:2px solid #dbf9ff;}
  .combat-vfx.cast-tide{animation:wispRipple .85s ease-out forwards;}
  .cast-aurora::before{background:conic-gradient(from 45deg,transparent 0 12%,#efb0dbbb 13% 15%,transparent 16% 37%,#ffd5f5 38% 40%,transparent 41% 62%,#efb0dbbb 63% 65%,transparent 66% 87%,#ffd5f5 88% 90%,transparent 91%);}
  .cast-aurora::after{inset:18%;border:2px solid #ffd5f5;transform:rotate(45deg);border-radius:12%;box-shadow:0 0 20px #df90c388;}
  .combat-vfx.cast-aurora{animation:wispBlessing .85s ease-out forwards;}
  .cast-stone::before{background:repeating-conic-gradient(from 5deg,transparent 0 15deg,#c2d9a4 16deg 20deg,transparent 21deg 60deg);clip-path:polygon(0 15%,40% 30%,55% 0,66% 36%,100% 45%,75% 64%,80% 100%,43% 77%,5% 95%,22% 50%);}
  .cast-stone::after{inset:22%;border:4px solid #c2d9a4;border-radius:20%;transform:rotate(25deg);}
  .combat-vfx.cast-stone{animation:wispSlam .7s ease-out forwards;}
  .cast-titan::before{border:5px double #ffe09b;border-radius:15%;transform:rotate(45deg);box-shadow:0 0 18px #ffbd4255;}
  .cast-titan::after{inset:27%;background:#fff1c9;clip-path:polygon(40% 0,60% 0,65% 35%,100% 40%,100% 60%,65% 65%,60% 100%,40% 100%,35% 65%,0 60%,0 40%,35% 35%);}
  .combat-vfx.cast-titan{animation:wispSlam .8s ease-out forwards;}
  .cast-gale::before{border:solid #b6f6ff;border-width:0 3px 0 0;border-radius:0;transform:skew(-25deg);box-shadow:-17px 0 #86dae699,17px 0 #86dae699;}
  .cast-gale::after{inset:25%;border:solid #e5fdff;border-width:0 2px 2px 0;border-radius:0;transform:rotate(45deg);}
  .combat-vfx.cast-gale{animation:wispVolley .65s ease-out forwards;}
  .cast-thorn::before{background:repeating-conic-gradient(#b8f5ab 0 15deg,transparent 16deg 60deg);clip-path:polygon(50% 0,62% 30%,90% 15%,75% 48%,100% 70%,65% 70%,50% 100%,35% 70%,0 70%,25% 48%,10% 15%,38% 30%);}
  .cast-thorn::after{inset:32%;border:2px solid #e4ffd8;}
  .combat-vfx.cast-thorn{animation:wispBloom .8s ease-out forwards;}
  .combat-vfx.vfx-shot{left:0;top:0;width:9px;height:9px;background:var(--vfx-color);box-shadow:0 0 9px var(--vfx-color);animation:wispShot .52s ease-in forwards;}
  .vfx-shot::after{content:'';position:absolute;inset:2px;border-radius:inherit;background:#f7f3db;}
  .vfx-shot.shot-ember{border-radius:70% 30% 60% 40%;width:11px;height:14px;}
  .vfx-shot.shot-void,.vfx-shot.shot-aurora{clip-path:polygon(50% 0,63% 35%,100% 50%,63% 65%,50% 100%,37% 65%,0 50%,37% 35%);width:15px;height:15px;}
  .vfx-shot.shot-stone,.vfx-shot.shot-titan{border-radius:2px;transform:rotate(30deg);}
  .vfx-shot.shot-gale{width:4px;height:19px;border-radius:50%;}
  .vfx-shot.shot-thorn{border-radius:0 90% 0 90%;width:9px;height:15px;}
  .vfx-shot.shot-tide{background:none;border:2px solid #9ee8ff;}
  .rift-wisp.is-attacking .wisp-portrait{filter:drop-shadow(0 0 4px var(--wisp-color));}
  @keyframes wispShot{0%{opacity:0;transform:translate(var(--from-x),var(--from-y)) scale(.7);}15%{opacity:.85;}78%{opacity:.9;}100%{opacity:0;transform:translate(var(--to-x),var(--to-y)) scale(.3);}}
  @keyframes wispCast{0%{opacity:0;transform:translate(-50%,-50%) scale(.2) rotate(-15deg);}22%{opacity:.85;}100%{opacity:0;transform:translate(-50%,-50%) scale(1.45) rotate(30deg);}}
  @keyframes wispVortex{0%{opacity:0;transform:translate(-50%,-50%) scale(1.3) rotate(0);}25%{opacity:.8;}100%{opacity:0;transform:translate(-50%,-50%) scale(.25) rotate(150deg);}}
  @keyframes wispRipple{0%{opacity:0;transform:translate(-50%,-50%) scale(.2,.1);}20%{opacity:.75;}100%{opacity:0;transform:translate(-50%,-50%) scale(1.6,.65);}}
  @keyframes wispBlessing{0%{opacity:0;transform:translate(-50%,-30%) scale(.35);}25%{opacity:.8;}100%{opacity:0;transform:translate(-50%,-80%) scale(1.2);}}
  @keyframes wispSlam{0%{opacity:0;transform:translate(-50%,-80%) scale(.4,.9);}25%{opacity:.85;transform:translate(-50%,-50%) scale(.85,.5);}100%{opacity:0;transform:translate(-50%,-50%) scale(1.5,.75);}}
  @keyframes wispVolley{0%{opacity:0;transform:translate(-50%,-100%) scale(.6);}30%{opacity:.85;}100%{opacity:0;transform:translate(-50%,0) scale(1.2);}}
  @keyframes wispBloom{0%{opacity:0;transform:translate(-50%,-50%) scale(.15) rotate(-45deg);}35%{opacity:.8;}100%{opacity:0;transform:translate(-50%,-50%) scale(1.4) rotate(30deg);}}
  @media(prefers-reduced-motion:reduce){.combat-vfx{display:none!important;}.rift-wisp.is-attacking .wisp-portrait{filter:none;}}

  /* Shared world: illustrated chapter headers and material surfaces.
     Decorations stay in their own boxes; Rift geometry is unchanged. */
  #tab-spirits{--chapter:#c3adff;--chapter-deep:#302044;}
  #tab-forge{--chapter:#ffc27b;--chapter-deep:#38241f;}
  #tab-research{--chapter:#83e4df;--chapter-deep:#143338;}
  #tab-ascend{--chapter:#c8b0ff;--chapter-deep:#29234b;}
  #tab-deeds{--chapter:#f2d491;--chapter-deep:#332e25;}
  .chapter-head{
    position:relative;isolation:isolate;display:flex;align-items:center;
    min-height:104px;margin:0 0 14px;padding:18px 16px;overflow:hidden;
    border:1px solid color-mix(in srgb,var(--chapter) 42%,#29364f);border-radius:16px;
    background:radial-gradient(ellipse at 90% 85%,var(--chapter-deep),transparent 65%),linear-gradient(115deg,#111b2e,#0c1424);
    box-shadow:inset 0 1px #ffffff14,0 9px 20px -16px #000;
  }
  .chapter-head::before{content:'';position:absolute;inset:5px;border:1px solid color-mix(in srgb,var(--chapter) 12%,transparent);border-radius:11px;pointer-events:none;}
  .chapter-copy{position:relative;z-index:1;max-width:65%;}
  .chapter-kicker{display:block;font-size:10px;line-height:15px;letter-spacing:.12em;text-transform:uppercase;color:var(--chapter);font-weight:800;margin-bottom:5px;}
  .chapter-head h2{font-size:23px;line-height:1.2;color:#fff1dc;font-weight:600;text-shadow:0 2px 12px #081022;}
  .chapter-art{position:absolute;right:-8px;bottom:0;width:180px;height:110px;pointer-events:none;}
  .chapter-art .scene-sparks{transform-origin:center;}
  .tab-panel.active .chapter-art .scene-sparks{animation:chapterAwaken 1.4s ease-out both;}
  @keyframes chapterAwaken{from{opacity:.15;transform:translateY(7px);}to{opacity:1;transform:none;}}
  .tab-panel:not(#tab-battle)>.section-sub{font-size:12px;line-height:1.55;margin:0 2px 14px;}
  .tab-panel:not(#tab-battle) .card{
    background:radial-gradient(ellipse at 100% 0%,color-mix(in srgb,var(--chapter) 8%,transparent),transparent 62%),linear-gradient(145deg,#1b2740,#111b2c);
    border-color:#43506a;box-shadow:inset 0 1px #ffffff0b,0 8px 20px -15px #000;
  }
  .tab-panel:not(#tab-battle) .section-label{color:var(--chapter);letter-spacing:.1em;}
  .tab-panel:not(#tab-battle) .section-label::after{background:linear-gradient(90deg,color-mix(in srgb,var(--chapter) 40%,transparent),transparent);}
  .tab-panel:not(#tab-battle) .card:focus-within{border-color:var(--chapter);}
  .tab-panel:not(#tab-battle) :is(.mini-btn,.buy-btn,.shop-card button):not(:disabled){
    background:linear-gradient(150deg,color-mix(in srgb,var(--chapter) 17%,#152138),#111a2c);
    border-color:color-mix(in srgb,var(--chapter) 70%,#4b5870);box-shadow:inset 0 1px #ffffff12;
  }
  .tab-panel:not(#tab-battle) :is(.mini-btn,.buy-btn,.speed-btn,.quest-claim-btn,.shop-card button):active:not(:disabled){
    box-shadow:inset 0 0 0 1px #f6e2b7,inset 0 0 16px #ffffff20;transform:translateY(1px);
  }
  .tab-panel:not(#tab-battle) .comet-purchase button:active:not(:disabled){transform:none;}
  .hud{background:linear-gradient(150deg,#152039,#0b1427);border-bottom-color:#44516b;backdrop-filter:none;}
  .hud .chip{border-radius:8px;border-color:#394760;background:linear-gradient(145deg,#202b43,#101a2e);}
  .hud .chip .lbl{opacity:1;color:#bdc7da;}
  .settings-btn,.settings-icon-btn{border-color:#56617c;background:linear-gradient(145deg,#2c3650,#141e32);color:#dfd9f3;}
  nav.tabbar{background:linear-gradient(180deg,#15213a,#0c1528);border-top-color:#586179;backdrop-filter:none;}
  nav.tabbar [data-tab="battle"]{--nav-accent:#f0c567;}
  nav.tabbar [data-tab="spirits"]{--nav-accent:#c3adff;}
  nav.tabbar [data-tab="forge"]{--nav-accent:#ffc27b;}
  nav.tabbar [data-tab="research"]{--nav-accent:#83e4df;}
  nav.tabbar [data-tab="ascend"]{--nav-accent:#c8b0ff;}
  nav.tabbar [data-tab="deeds"]{--nav-accent:#f2d491;}
  nav.tabbar button.active{color:var(--nav-accent);background:radial-gradient(ellipse at 50% 0%,color-mix(in srgb,var(--nav-accent) 15%,transparent),transparent 78%);}
  nav.tabbar button.active::after{left:24%;right:24%;height:2px;opacity:1;}
  #tab-spirits .hero-card:not(.locked){border-color:color-mix(in srgb,var(--wisp-color) 40%,#35445d);background:radial-gradient(ellipse at 0 0,color-mix(in srgb,var(--wisp-color) 13%,transparent),transparent 60%),linear-gradient(140deg,#1d2940,#121c30);}
  #tab-spirits .hero-card::before{width:3px;opacity:1;}
  .hero-top .wisp-portrait{width:58px;height:58px;padding:4px;border-radius:50%;border-color:color-mix(in srgb,var(--wisp-color) 65%,#303f59);background:radial-gradient(circle,color-mix(in srgb,var(--wisp-color) 22%,#101a2c),#0b1324 70%);box-shadow:0 0 0 3px #0c1728,inset 0 0 0 3px #172338;filter:none;}
  #tab-spirits .hero-id .name{font-family:'Cinzel',serif;font-size:16px;line-height:1.3;color:#f9ebd7;}
  #tab-spirits .hero-card .class-tag{color:color-mix(in srgb,var(--wisp-color,#c3adff) 55%,#fff)!important;}
  #tab-spirits .hero-card.active-wisp{box-shadow:inset 0 2px color-mix(in srgb,var(--wisp-color) 60%,transparent),0 8px 20px -15px #000;}
  .hero-stat-pill{border-radius:6px;background:#0f1b2e;border-color:#3c4b64;}
  .hero-card .rarity-badge{border-radius:6px;}
  .hero-card .module-row{border-color:#45506b;background:linear-gradient(145deg,#18243b,#0e182a);}
  .hero-card .ultimate-badge{border-color:#c49667;background:linear-gradient(120deg,#3b2940,#28223c);color:#ffd5a7;}
  .formation-preset-card .formation-lineup{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:4px;padding:6px;background:#0d1729;border:1px solid #3e4b65;border-radius:10px;}
  .formation-member{flex-direction:column;min-width:0;color:#ece5f8;}
  #tab-forge .card.node-card{display:block;border-left:3px solid #cf955d;padding:12px;}
  .forge-head{display:flex;align-items:center;gap:10px;margin-bottom:8px;}
  .forge-head .node-info{flex:1;min-width:0;}
  .forge-head .lvl{color:#d0c2a7;font-size:11px;margin-top:3px;}
  .forge-description{font-size:12px;line-height:1.45;color:var(--ink-dim);}
