  .forge-actions .buy-btn .cost{font-size:12px;}
  .upgrade-emblem{width:32px;height:38px;flex:none;color:var(--chapter);}
  #tab-forge [data-forge-preview]{white-space:pre-line;overflow-wrap:anywhere;font-size:12px;line-height:1.45;margin-top:8px;padding:8px 10px;border:1px solid #3e4a61;border-radius:8px;background:#0e192b;}
  #tab-forge .node-info>.name{color:#ffe0b6;}
  #tab-forge .node-card.locked-node{border-left-color:#5b6477;}
