  .study-slot-summary strong{color:#c8fff0;}
  #tab-research .card.study-running{border-left-color:#83e4df;background:radial-gradient(ellipse at 100% 0%,#26545b66,transparent 65%),linear-gradient(145deg,#182e3d,#111e31);}
  .study-running-label{color:#a5ede5;letter-spacing:.06em;text-transform:uppercase;font-size:10px;}
  .study-bar-track{height:12px;background:#0a1625;border-color:#4c6574;}
  .study-bar-fill{background:linear-gradient(90deg,#497d9d,#8edecf);box-shadow:inset 0 1px #c6fff2;}
  .study-card .name{color:#d0f1ec;}
  .study-inspection{margin-top:8px;border-top:1px solid #40576a;}
  .ascend-summary>.chapter-head{align-self:stretch;margin:-1px -1px 4px;text-align:left;min-height:116px;}
  .ascend-summary .chapter-art{width:192px;height:118px;}
