  /* NAV-001 navigation. Five stable main destinations. */
  :root{--nav-lift:8px;}
  .shell,.shell:has(#tab-battle.active){--nav-height:54px;}
  @media(max-height:650px){
    .shell,.shell:has(#tab-battle.active){--nav-height:48px;}
    /* Reclaim decorative vertical padding for the raised nav on short Rifts. */
    #tab-battle .stage{padding-top:0;padding-bottom:0;}
  }
  main{margin-bottom:calc(var(--nav-height) + var(--safe-bottom) + var(--nav-lift));}
  #toast{bottom:calc(var(--nav-height) + var(--safe-bottom) + var(--nav-lift) + 8px);}
  nav.tabbar{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));isolation:isolate;overflow:visible;background:linear-gradient(180deg,#142037,#0b1528);border-top-color:#344158;box-shadow:0 -8px 28px -18px #0008;}
  nav.tabbar button{min-width:0;min-height:44px;padding:3px 2px;display:grid;grid-template-rows:minmax(0,1fr) 12px;gap:1px;justify-items:center;align-items:center;color:#a5b1c7;transition:color .18s ease;}
  nav.tabbar button:active{transform:none;}
  nav.tabbar .nav-icon{position:relative;isolation:isolate;width:36px;height:28px;display:flex;align-items:center;justify-content:center;border-radius:10px;transition:background .18s ease,box-shadow .18s ease,color .18s ease;}
  nav.tabbar .nav-icon::after{content:'';position:absolute;inset:-1px;border-radius:inherit;pointer-events:none;opacity:0;}
  nav.tabbar .nav-feedback .nav-icon::after{animation:navHalo .3s ease-out;}
  nav.tabbar .nav-feedback .nav-art{animation:navLight .28s ease-out;}
  @keyframes navHalo{0%{opacity:.7;box-shadow:0 0 0 0 color-mix(in srgb,currentColor 35%,transparent);}100%{opacity:0;box-shadow:0 0 0 5px color-mix(in srgb,currentColor 8%,transparent);}}
  @keyframes navLight{0%{filter:brightness(1.18) drop-shadow(0 0 3px currentColor);}100%{filter:none;}}
  nav.tabbar .nav-art{width:22px;height:22px;stroke-width:1.7;}
  nav.tabbar button .lb{font-size:10px;line-height:12px;white-space:nowrap;letter-spacing:0;}
  nav.tabbar button.active .lb{visibility:hidden;}
  nav.tabbar button.active{--nav-accent:#edf1fa;color:var(--nav-accent);background:none;}
  nav.tabbar button.active .nav-icon{background:linear-gradient(180deg,#2a3750,#1b283f);box-shadow:inset 0 1px #e6eeff25,inset 0 0 0 1px #c7d5ef17,0 2px 8px #0002;}
  nav.tabbar button.active .nav-art{stroke-width:1.9;filter:none;}
  nav.tabbar button.active::after{width:4px;height:4px;left:calc(50% - 2px);right:auto;bottom:7px;border-radius:50%;background:#c7d2e5;opacity:.9;}
  nav.tabbar [data-tab="battle"] .nav-icon{position:absolute;top:-7px;width:42px;height:42px;border-radius:50%;border:1px solid #7b6b46;background:linear-gradient(145deg,#27344b,#101c30);box-shadow:0 3px 10px #0006,inset 0 1px #f0c56724;}
  nav.tabbar [data-tab="battle"] .nav-art{width:26px;height:26px;color:#f0c567;}
  nav.tabbar [data-tab="battle"] .lb{grid-row:2;}
  nav.tabbar [data-tab="battle"].active{--nav-accent:#f0c567;}
  nav.tabbar [data-tab="battle"]::after{content:none;display:none;}
  nav.tabbar [data-tab="battle"].active .nav-icon{border-color:#bfa16a;background:radial-gradient(circle at 50% 25%,#3e403e,#162138 78%);box-shadow:0 0 14px #f0c56718,inset 0 1px #f0c56724;}
  nav.tabbar button:active .nav-art{filter:brightness(1.15);}
