  .cast-thorn::before{background:repeating-conic-gradient(#b8f5ab 0 15deg,transparent 16deg 60deg);clip-path:polygon(50% 0,62% 30%,90% 15%,75% 48%,100% 70%,65% 70%,50% 100%,35% 70%,0 70%,25% 48%,10% 15%,38% 30%);}
  .cast-thorn::after{inset:32%;border:2px solid #e4ffd8;}
  .combat-vfx.cast-thorn{animation:wispBloom .8s ease-out forwards;}
  .combat-vfx.vfx-shot{left:0;top:0;width:9px;height:9px;background:var(--vfx-color);box-shadow:0 0 9px var(--vfx-color);animation:wispShot .52s ease-in forwards;}
  .vfx-shot::after{content:'';position:absolute;inset:2px;border-radius:inherit;background:#f7f3db;}
  .vfx-shot.shot-ember{border-radius:70% 30% 60% 40%;width:11px;height:14px;}
  .vfx-shot.shot-void,.vfx-shot.shot-aurora{clip-path:polygon(50% 0,63% 35%,100% 50%,63% 65%,50% 100%,37% 65%,0 50%,37% 35%);width:15px;height:15px;}
  .vfx-shot.shot-stone,.vfx-shot.shot-titan{border-radius:2px;transform:rotate(30deg);}
  .vfx-shot.shot-gale{width:4px;height:19px;border-radius:50%;}
  .vfx-shot.shot-thorn{border-radius:0 90% 0 90%;width:9px;height:15px;}
  .vfx-shot.shot-tide{background:none;border:2px solid #9ee8ff;}
  .rift-wisp.is-attacking .wisp-portrait{filter:drop-shadow(0 0 4px var(--wisp-color));}
  @keyframes wispShot{0%{opacity:0;transform:translate(var(--from-x),var(--from-y)) scale(.7);}15%{opacity:.85;}78%{opacity:.9;}100%{opacity:0;transform:translate(var(--to-x),var(--to-y)) scale(.3);}}
  @keyframes wispCast{0%{opacity:0;transform:translate(-50%,-50%) scale(.2) rotate(-15deg);}22%{opacity:.85;}100%{opacity:0;transform:translate(-50%,-50%) scale(1.45) rotate(30deg);}}
  @keyframes wispVortex{0%{opacity:0;transform:translate(-50%,-50%) scale(1.3) rotate(0);}25%{opacity:.8;}100%{opacity:0;transform:translate(-50%,-50%) scale(.25) rotate(150deg);}}
  @keyframes wispRipple{0%{opacity:0;transform:translate(-50%,-50%) scale(.2,.1);}20%{opacity:.75;}100%{opacity:0;transform:translate(-50%,-50%) scale(1.6,.65);}}
  @keyframes wispBlessing{0%{opacity:0;transform:translate(-50%,-30%) scale(.35);}25%{opacity:.8;}100%{opacity:0;transform:translate(-50%,-80%) scale(1.2);}}
  @keyframes wispSlam{0%{opacity:0;transform:translate(-50%,-80%) scale(.4,.9);}25%{opacity:.85;transform:translate(-50%,-50%) scale(.85,.5);}100%{opacity:0;transform:translate(-50%,-50%) scale(1.5,.75);}}
  @keyframes wispVolley{0%{opacity:0;transform:translate(-50%,-100%) scale(.6);}30%{opacity:.85;}100%{opacity:0;transform:translate(-50%,0) scale(1.2);}}
  @keyframes wispBloom{0%{opacity:0;transform:translate(-50%,-50%) scale(.15) rotate(-45deg);}35%{opacity:.8;}100%{opacity:0;transform:translate(-50%,-50%) scale(1.4) rotate(30deg);}}
