  .tab-panel:not(#tab-battle) .section-label::after{background:linear-gradient(90deg,color-mix(in srgb,var(--chapter) 40%,transparent),transparent);}
  .tab-panel:not(#tab-battle) .card:focus-within{border-color:var(--chapter);}
  .tab-panel:not(#tab-battle) :is(.mini-btn,.buy-btn,.shop-card button):not(:disabled){
    background:linear-gradient(150deg,color-mix(in srgb,var(--chapter) 17%,#152138),#111a2c);
    border-color:color-mix(in srgb,var(--chapter) 70%,#4b5870);box-shadow:inset 0 1px #ffffff12;
  }
  .tab-panel:not(#tab-battle) :is(.mini-btn,.buy-btn,.speed-btn,.quest-claim-btn,.shop-card button):active:not(:disabled){
