function checkAffordability(){
  var now = Date.now();
  if(Amount.lt(Amount.sub(now,lastAffordabilityAt),AFFORDABILITY_REFRESH_MS)) return;
  lastAffordabilityAt = now;
  renderLabCapacityBadge();
  var actionView=captureWispActionView();
  els['spirit-list'].querySelectorAll('[data-empower]').forEach(function(btn){
    var sp = SPIRITS.find(function(s){ return s.id===btn.getAttribute('data-empower'); });
    if(!sp) return;
    var plan=getSpiritBuyPlan(sp),label=btn.querySelector('strong');
    btn.disabled=!plan.affordable;
    if(label) label.textContent=plan.reason==='unavailable'?'Unavailable':Amount.gt(state.spirits[sp.id]||0,0)?'Empower':'Recruit';
  });
  els['spirit-list'].querySelectorAll('[data-rarity]').forEach(function(btn){
    var id = btn.getAttribute('data-rarity');
    var sp = SPIRITS.find(function(s){ return s.id===id; });
    if(!sp) return;
    var tier = state.heroRarity[id]||0;
    if(Amount.ge(tier,5)){ btn.disabled = true; return; }
    var level = state.spirits[id];
    var req = rarityReq(tier);
    var cost = rarityCost(sp, tier);
    btn.disabled = !getWispRarityPlan(sp).affordable;
  });
  els['spirit-list'].querySelectorAll('[data-module]').forEach(function(btn){
    var sp = SPIRITS.find(function(s){ return s.id===btn.getAttribute('data-module'); });
    if(!sp) return;
    var level = moduleLevel(sp.id);
    if(Amount.ge(level,MODULE_MAX_LEVEL)) return;
    var cost = moduleCost(sp, level);
    btn.disabled = Amount.le(state.spirits[sp.id]||0,0) || Amount.lt(state.lumen,cost.lumen) || !canSpendShards(cost.shard);
  });
  els['spirit-list'].querySelectorAll('[data-ultimate]').forEach(function(btn){
    var sp = SPIRITS.find(function(s){ return s.id===btn.getAttribute('data-ultimate'); });
    if(!sp) return;
    btn.disabled = !getWispUltimatePlan(sp).affordable;
  });
  els['spirit-list'].querySelectorAll('[data-mastery]').forEach(function(btn){
    var sp=SPIRITS.find(function(s){return s.id===btn.getAttribute('data-mastery');});if(sp)btn.disabled=!getWispMasteryPlan(sp).affordable;
  });
  els['spirit-list'].querySelectorAll('[data-sigil-resonate]').forEach(function(btn){
    var sp=SPIRITS.find(function(s){return s.id===btn.getAttribute('data-sigil-resonate');});
    btn.disabled=!canSigilResonate(sp);
  });
  restoreWispActionView(actionView);
  els['research-list'].querySelectorAll('[data-research]').forEach(function(btn){
    var node = RESEARCH.find(function(n){ return n.id===btn.getAttribute('data-research'); });
    if(!node) return;
    updateResearchCard(node,btn.closest('[data-forge-card]'));
  });
  if(els['hud-mote'])els['hud-mote'].title=state.moteNextAtMs>Date.now()?'Luminous Motes ready in '+fmtStudyDuration((state.moteNextAtMs-Date.now())/1000):'Luminous Mote payout ready';
  var openStudySlots = studySlotCount() - state.activeStudies.length;
  els['study-list'].querySelectorAll('[data-study]').forEach(function(btn){
    var lnode = LONG_STUDIES.find(function(n){ return n.id===btn.getAttribute('data-study'); });
    if(!lnode) return;
    btn.disabled = !getStudyStartPlan(lnode).affordable;
  });
  els['study-list'].querySelectorAll('[data-speed-study]').forEach(function(btn){
    btn.disabled=!getStudyBoostPlan(btn.getAttribute('data-speed-study'),Number(btn.getAttribute('data-speed')),Number(btn.getAttribute('data-hours'))).affordable;
  });
  els['node-list'].querySelectorAll('[data-node]').forEach(function(btn){
    var node=NODES.find(function(n){return n.id===btn.getAttribute('data-node');});
    if(node) btn.disabled=!getNodeBuyPlan(node).affordable;
  });
  SHOP.forEach(function(item){updateCometShopCard(item,els['shop-list'].querySelector(('[data-comet-card="' + item.id + '"]')));});
  els['daily-quest-list'].querySelectorAll('[data-quest-refresh]').forEach(function(btn){
    btn.disabled=!getDailyQuestRefreshPlan(btn.getAttribute('data-quest-refresh')).available;
  });
  renderCometCommands();
  ['spirit-list','research-list','study-list','node-list','shop-list','daily-quest-list'].forEach(function(id){
    updatePurchasePriceColors(els[id]);
    presentControlStates(els[id]);
  });
  renderAutoAscendControls();
}

function replaceControlMarkup(root,html,keepAutoAscend,focusHandled,preparedMarkup){
  var focused=document.activeElement;
  var previous=root.contains(focused) ? focused : null;
  var keys=previous ? Array.from(previous.attributes).filter(function(a){return a.name.startsWith('data-') && a.name!=='data-state';}) : [];
  var index=previous ? Array.from(root.querySelectorAll('button,select,input')).indexOf(previous) : -1;
  var stable=keepAutoAscend && root.querySelector('[data-autoascend-card]');
  var trialCard=keepAutoAscend && previous && previous.matches('input,select') && previous.closest('[data-comet-trial-card]');
  if(preparedMarkup){
    // Adopt fully prepared off-DOM cards without serializing and parsing again.
    var fragment=document.createDocumentFragment();
    while(preparedMarkup.firstChild)fragment.appendChild(preparedMarkup.firstChild);
    root.textContent='';root.appendChild(fragment);
  } else if(stable || trialCard){
    // Keep the real native select attached while unrelated shop cards refresh.
    var prepared=document.createElement('div');prepared.innerHTML=html;
    var children=Array.from(prepared.children),nextCard=prepared.querySelector('[data-autoascend-card]');
    var nextTrial=prepared.querySelector('[data-comet-trial-card]');
    var keepTrial=trialCard && nextTrial && nextTrial.querySelector('[data-trial-choice]');
    if(keepTrial) children[children.indexOf(nextTrial)]=trialCard;
    if((nextCard && children.indexOf(nextCard)===Array.from(root.children).indexOf(stable)) || (!stable && keepTrial)){
      if(stable){
        var toggle=stable.querySelector('[data-autoascend-toggle]'),nextToggle=nextCard.querySelector('[data-autoascend-toggle]');
        toggle.className=nextToggle.className;toggle.textContent=nextToggle.textContent;
      }
      children.forEach(function(child,i){
        if(child===nextCard || child===trialCard) return;
        if(root.children[i]) root.children[i].replaceWith(child);else root.appendChild(child);
      });
      while(root.children.length>children.length) root.lastElementChild.remove();
    } else root.innerHTML=html;
  } else root.innerHTML=html;
  if(!preparedMarkup)presentControlStates(root);
  if(previous && !previous.isConnected && !focusHandled){
    var buttons=Array.from(root.querySelectorAll('button,select,input'));
    var replacement=keys.length && buttons.find(function(btn){return keys.every(function(a){return btn.getAttribute(a.name)===a.value;});});
    if(replacement && !replacement.disabled) replacement.focus({preventScroll:true});
    else {
      var next=buttons.slice(Math.max(0,index)).concat(buttons.slice(0,Math.max(0,index))).find(function(btn){return !btn.disabled;});
      if(next) next.focus({preventScroll:true});
      else { root.tabIndex=-1;root.focus({preventScroll:true}); }
    }
  }
}

function getCometCommandPlan(id){
  var known=id==='meteor' || id==='starcall';
  var target={depth:state.depth,hp:state.enemyHp,maxHp:state.enemyMaxHp,
    boss:isBoss(state.depth),luminous:state.enemyIsLuminous};
  var valid=Amount.valid(target.hp) && Amount.valid(target.maxHp) &&
    Amount.gt(target.hp,0) && Amount.le(target.hp,target.maxHp) && state.enemyDepth===state.depth;
  var plan={id:id,owned:known && state.owned[id]===true,charges:state.cometCharges,cost:1,
    target:target,available:false,reason:'unavailable'};
  if(id==='meteor' && valid) plan.meteor=cometMeteorHpPlan(target.maxHp,target.hp,
    passiveWispDpsAt(state.depth),cometUpgradeLevel('meteorcore'));
  if(!known) return plan;
  if(!plan.owned) plan.reason='unowned';
  else if(!cometMutationOpen() || autoAscendReady()) plan.reason='inactive';
  else if(!valid) plan.reason='target';
  else if(id==='meteor' && state.cometMeteorUsed) plan.reason='used';
  else if(id==='starcall' && target.boss) plan.reason='boss';
  else if(id==='starcall' && target.luminous) plan.reason='luminous';
  else if(Amount.lt(state.cometCharges,1)) plan.reason='charge';
  else if(id==='meteor' && !plan.meteor.available) plan.reason=plan.meteor.reason;
  else {plan.reason='available';plan.available=true;}
  return plan;
}

  /* Lumenfall deliberately uses one dark palette, independent of system appearance. */
  :root{
    --bg:#0d0f1f;--bg-elev:#161933;--bg-elev-2:#1f2344;
    --ink:#f0effb;--ink-dim:#b5b4cb;--line:#3b4060;
    --lumen:#f0c567;--shard:#82d2ec;--mote:#ffb4d5;--prism:#bd9bef;
    --comet:#5ee6d0;--sigil:#ffa17b;--danger:#ff7b92;--good:#9ed9b1;
    --shadow:0 1px 2px #0006,0 12px 32px -12px #0009;
    color-scheme:dark;
  }

  *{box-sizing:border-box;}
  html,body{margin:0;padding:0;background:var(--bg);color:var(--ink);}
  body{
    font-family:'Manrope',system-ui,-apple-system,sans-serif;
    min-height:100vh;
    overflow-x:hidden;
    -webkit-tap-highlight-color: transparent;
  }
  h1,h2,h3{font-family:'Cinzel',Georgia,serif;text-wrap:balance;margin:0;}
  .mono{font-family:'IBM Plex Mono',ui-monospace,monospace;font-variant-numeric:tabular-nums;}
  button{font-family:inherit;}
  :focus-visible{outline:2px solid var(--prism);outline-offset:2px;border-radius:4px;}

  canvas#stars{position:fixed;inset:0;width:100%;height:100%;z-index:0;pointer-events:none;}

  .shell{
    position:relative;z-index:1;
    max-width:460px;margin:0 auto;
    min-height:100vh;
    display:flex;flex-direction:column;
    background:color-mix(in srgb, var(--bg-elev) 88%, transparent);
    backdrop-filter: blur(6px);
    border-left:1px solid var(--line);
    border-right:1px solid var(--line);
  }

  :root{--safe-top:env(safe-area-inset-top,0px);--safe-bottom:env(safe-area-inset-bottom,0px);--nav-height:54px;}

  /* ---------- HUD ---------- */
  .topbar{position:sticky;top:0;z-index:6;}
  .hud{
    display:flex;align-items:center;gap:6px;flex-wrap:wrap;
    padding:10px 12px;
    background:color-mix(in srgb, var(--bg-elev) 92%, transparent);
    backdrop-filter: blur(10px);
    border-bottom:1px solid var(--line);
  }
  .chip{
    display:flex;align-items:center;gap:5px;
    padding:5px 9px;border-radius:999px;
    background:var(--bg-elev-2);
    border:1px solid var(--line);
    flex:1 1 auto;min-width:0;
  }
  .chip .lbl{font-size:.6rem;font-weight:700;text-transform:uppercase;letter-spacing:.03em;color:var(--ink-dim);}
  .chip .val{font-size:.78rem;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
  .glyph-icon{flex:none;width:13px;height:13px;}
  .hud-title-row{display:flex;align-items:center;width:100%;gap:8px;margin-bottom:2px;}
  .hud .brand{
    font-family:'Cinzel',serif;font-weight:700;font-size:1rem;letter-spacing:.02em;
    color:var(--ink);flex:1;min-width:0;
  }
  .settings-btn{
    width:34px;height:34px;border-radius:10px;border:1px solid var(--line);
    background:var(--bg-elev-2);color:var(--ink-dim);font-size:1.05rem;
    display:flex;align-items:center;justify-content:center;cursor:pointer;flex:none;
  }
  .settings-btn:active{transform:scale(.96);}

  /* ---------- main ---------- */
  main{flex:1;padding:14px 12px 24px;}
  .tab-panel{display:none;animation: fade .25s ease;}
  .tab-panel.active{display:block;}
  @keyframes fade{from{opacity:0;transform:translateY(4px);}to{opacity:1;transform:none;}}

  .card{
    background:var(--bg-elev-2);
    border:1px solid var(--line);
    border-radius:14px;
    padding:14px;
    box-shadow:var(--shadow);
  }
  .section-label{
    font-size:.7rem;text-transform:uppercase;letter-spacing:.08em;
    color:var(--ink-dim);font-weight:700;margin:18px 2px 8px;
  }
  .section-label:first-child{margin-top:0;}
  .section-sub{font-size:.78rem;color:var(--ink-dim);margin:-4px 2px 12px;}

  /* ---------- reusable buy button ---------- */
  .buy-btn{
    flex:none;display:flex;flex-direction:column;align-items:center;gap:2px;
    border:1px solid var(--line);background:var(--bg-elev);border-radius:10px;
    padding:7px 10px;cursor:pointer;color:var(--ink);min-width:78px;
  }
  .buy-btn .cost{font-size:.74rem;font-weight:700;display:flex;align-items:center;justify-content:center;gap:2px;}
  .buy-btn .label{font-size:.6rem;color:var(--ink-dim);text-transform:uppercase;letter-spacing:.04em;}
  .buy-btn:disabled{opacity:1;cursor:not-allowed;}
  .lock-note{font-size:.72rem;color:var(--ink-dim);font-style:italic;}

  /* ---------- Battle stage ---------- */
  .stage{padding:16px 14px;display:flex;flex-direction:column;gap:10px;}
  .depth-label{font-size:.78rem;color:var(--ink-dim);font-weight:700;letter-spacing:.04em;text-align:center;}
  .depth-label .boss-tag{color:var(--danger);}
  .depth-label .region-label{display:block;font-size:.6rem;letter-spacing:.08em;text-transform:uppercase;margin-top:2px;}
  .enemy-name{font-family:'Cinzel',serif;font-size:1rem;font-weight:600;text-align:center;}

  .battle-row{display:flex;gap:10px;align-items:flex-start;}
  .party-col{width:60px;flex:none;display:flex;flex-direction:column;gap:6px;}
  .hero-chip{
    position:relative;display:flex;flex-direction:column;align-items:center;gap:3px;
    background:var(--bg-elev);border:1px solid var(--line);border-radius:9px;padding:5px 2px 6px;
  }
  .hero-chip .shape{width:20px;height:20px;}
  .chip-bar-track{width:32px;height:3px;border-radius:999px;background:var(--line);overflow:hidden;}
  .chip-bar-fill{height:100%;width:0%;transition:width .1s linear;}
  .chip-label{font-size:.5rem;color:var(--ink-dim);font-weight:700;max-width:36px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
  .chip-power{font-family:'IBM Plex Mono',monospace;font-size:.5rem;color:var(--ink);font-weight:600;max-width:36px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
  .hero-chip.pulse{animation:pulseChip .3s ease;}
  .hero-chip.unpowered{opacity:.5;}
  @keyframes pulseChip{0%{transform:scale(1);}50%{transform:scale(1.18);}100%{transform:scale(1);}}
  .chip-flash{
    position:absolute;top:-13px;left:50%;transform:translateX(-50%);
    font-size:.5rem;font-weight:700;white-space:nowrap;pointer-events:none;
    animation: floatUp .8s ease-out forwards;
  }
  .empty-party-note{font-size:.66rem;color:var(--ink-dim);text-align:center;line-height:1.3;padding-top:4px;}

  .enemy-stage-wrap{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:8px;}
  .enemy-stage{
    position:relative;width:128px;height:128px;
    display:flex;align-items:center;justify-content:center;
    cursor:pointer;user-select:none;touch-action:manipulation;
  }
  .enemy-stage::before{
    content:'';position:absolute;inset:-16px;border-radius:50%;pointer-events:none;
    background: radial-gradient(circle, color-mix(in srgb, var(--theme-accent, var(--zone-accent, transparent)) 45%, transparent) 0%, transparent 72%);
  }
  .enemy-stage.theme-radiant::before{
    background: conic-gradient(from 0deg, var(--lumen), var(--shard), var(--mote), var(--prism), var(--comet), var(--sigil), var(--lumen));
    opacity:.4;filter:blur(4px);
  }
  .enemy-glyph{
    width:92px;height:92px;
    background: linear-gradient(160deg, var(--danger), color-mix(in srgb, var(--danger) 60%, #3a1030));
    border-radius: 63% 37% 54% 46% / 43% 47% 53% 57%;
    box-shadow: 0 0 40px -6px color-mix(in srgb, var(--danger) 60%, transparent);
    transition: transform .08s ease;
  }
  .enemy-glyph.boss{
    border-radius:0;
    clip-path: polygon(50% 0%,61% 35%,98% 35%,68% 57%,79% 91%,50% 70%,21% 91%,32% 57%,2% 35%,39% 35%);
    width:104px;height:104px;
  }
  .enemy-glyph.luminous{
    box-shadow: 0 0 46px 8px color-mix(in srgb, var(--mote) 65%, transparent);
    filter: brightness(1.18) saturate(1.1);
  }
  .enemy-stage.hit .enemy-glyph{transform:scale(.9) rotate(-2deg);}
  .hp-wrap{width:100%;}
  .hp-bar-track{height:9px;border-radius:999px;background:var(--bg-elev-2);border:1px solid var(--line);overflow:hidden;}
  .hp-bar-fill{height:100%;background:linear-gradient(90deg, var(--danger), color-mix(in srgb, var(--danger) 70%, #ffb56b));width:100%;transition:width .12s linear;}
  .hp-text{font-size:.68rem;color:var(--ink-dim);margin-top:4px;text-align:center;}
  .boss-regen-tag{font-size:.66rem;color:var(--good);font-weight:700;text-align:center;margin-top:4px;}
  .boss-regen-tag.insufficient{color:var(--danger);}
  .buff-indicator{font-size:.72rem;color:var(--good);font-weight:700;text-align:center;}
  .float-num{
    position:absolute;left:50%;top:20%;transform:translateX(-50%);
    font-family:'IBM Plex Mono',monospace;font-weight:600;font-size:.82rem;
    color:var(--lumen);pointer-events:none;
    animation: floatUp .7s ease-out forwards;
  }
  @keyframes floatUp{
    0%{opacity:1;transform:translate(-50%,0);}
    100%{opacity:0;transform:translate(-50%,-44px);}
  }
  .tap-hint{font-size:.7rem;color:var(--ink-dim);text-align:center;}
  .stat-row{display:flex;gap:8px;width:100%;}
  .stat-box{flex:1;background:var(--bg-elev-2);border:1px solid var(--line);border-radius:10px;padding:8px 10px;text-align:left;}
  .stat-box .k{font-size:.63rem;color:var(--ink-dim);text-transform:uppercase;letter-spacing:.05em;}
  .stat-box .v{font-size:.88rem;font-weight:600;margin-top:2px;}
  .rift-mode-row{display:flex;gap:7px;width:100%;align-items:center;}
  .rift-mode-btn{
    flex:1;border:1px solid var(--line);background:var(--bg-elev);color:var(--ink-dim);
    border-radius:9px;padding:7px 8px;font-size:.68rem;font-weight:800;cursor:pointer;
  }
  .rift-mode-btn.active{border-color:var(--lumen);color:var(--lumen);background:color-mix(in srgb,var(--lumen) 10%,var(--bg-elev));}
  .rift-mode-btn:disabled{opacity:1;cursor:not-allowed;}
  .rift-mode-note{font-size:.66rem;color:var(--ink-dim);text-align:center;line-height:1.4;margin-top:-3px;}

  /* ---------- shapes ---------- */
  .shape{display:inline-block;flex:none;}
  .shape-triangle{clip-path: polygon(50% 0%, 0% 100%, 100% 100%);}
  .shape-hex{clip-path: polygon(25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%, 0% 50%);}
  .shape-diamond{clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);}
  .shape-pentagon{clip-path: polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%);}
  .shape-star{clip-path: polygon(50% 0%,61% 35%,98% 35%,68% 57%,79% 91%,50% 70%,21% 91%,32% 57%,2% 35%,39% 35%);}
  .shape-octagon{clip-path: polygon(30% 0%, 70% 0%, 100% 30%, 100% 70%, 70% 100%, 30% 100%, 0% 70%, 0% 30%);}
  .shape-droplet{border-radius:60% 60% 60% 0%;transform:rotate(45deg);}
  .shape-ring{border-radius:50%;background:transparent !important;box-sizing:border-box;}

  /* ---------- Hero roster ---------- */
  .hero-grid{display:grid;grid-template-columns:1fr;gap:10px;}
  .hero-card.locked{opacity:1;}
  .hero-top{display:flex;align-items:center;gap:10px;}
  .hero-top .shape{width:34px;height:34px;}
  .hero-card .shape-ring{border:6px solid currentColor;}
  .hero-card.locked .shape{background:var(--ink-dim) !important;}
  .hero-id{flex:1;min-width:0;}
  .hero-id .name{font-weight:700;font-size:.9rem;}
  .class-tag{font-size:.65rem;font-weight:700;text-transform:uppercase;letter-spacing:.03em;margin-top:1px;}
  .module-row{margin-top:8px;padding:8px 10px;border-radius:10px;background:var(--bg-elev);border:1px solid var(--line);}
  .module-name{font-size:.76rem;font-weight:700;}
  .module-effect{font-size:.68rem;color:var(--ink-dim);margin-top:2px;}
  .module-row .mini-btn{width:100%;margin-top:8px;}
  .ultimate-row{margin-top:8px;}
  .ultimate-badge{
    font-size:.7rem;font-weight:700;text-align:center;padding:8px;border-radius:10px;
    background:color-mix(in srgb, var(--sigil) 16%, transparent);
    color:var(--sigil);border:1px solid color-mix(in srgb, var(--sigil) 40%, transparent);
  }
  .ultimate-btn{width:100%;}
  .sigil-resonance-btn{width:100%;margin-top:6px;color:var(--sigil);}
  .sigil-resonance-help{margin:6px 0 0;font-size:.75rem;line-height:1.5;color:var(--ink-dim);}
  .quest-actions{display:flex;align-items:center;gap:6px;flex:none;}
  .quest-refresh-btn{border-color:var(--comet);background:var(--bg-elev);color:var(--comet);}
  .node-queue-toggle{
    margin-left:6px;padding:2px 8px;border-radius:999px;font-size:.6rem;font-weight:700;
    border:1px solid var(--line);background:var(--bg-elev);color:var(--ink-dim);cursor:pointer;
    vertical-align:middle;
  }
  .node-queue-toggle.active{background:var(--good);border-color:var(--good);color:#fff;}
  .active-toggle{
    flex:none;font-size:.6875rem;font-weight:700;padding:5px 10px;border-radius:999px;
    border:1px solid var(--line);background:var(--bg-elev);color:var(--ink-dim);cursor:pointer;
  }
  .active-toggle.is-active{background:var(--good);color:#08210f;border-color:var(--good);}
  .wisp-role-readout{margin:8px 0;padding:8px 0;border-top:1px solid var(--line);}
  .wisp-role-readout:empty{display:none;}
  .wisp-role-line{display:flex;flex-wrap:wrap;justify-content:space-between;gap:4px 12px;margin:5px 0;font-size:.8125rem;line-height:1.5;}
  .wisp-role-line strong{max-width:100%;overflow-wrap:break-word;}
  .wisp-role-note{margin:6px 0;font-size:.8125rem;line-height:1.5;color:var(--ink);}
  .wisp-role-readout,.wisp-role-line,.wisp-role-note{animation:none!important;transition:none!important;}
  .hero-stats{font-size:.72rem;color:var(--ink-dim);margin:8px 0 6px;}
  .hero-ability{font-size:.7rem;color:var(--ink-dim);margin-bottom:8px;line-height:1.4;}
  .bond-card{margin-bottom:12px;padding:12px;}
