  .bond-summary{font-size:.66rem;color:var(--ink-dim);text-align:center;line-height:1.35;margin-top:8px;min-height:1em;}
  .hero-ability strong{color:var(--ink);}
  .hero-actions{display:flex;gap:8px;}
  .mini-btn{
    flex:1;border-radius:9px;border:1px solid var(--line);background:var(--bg-elev);color:var(--ink);
