    border:1px solid var(--line);background:var(--bg-elev);color:var(--ink);
    font-size:.68rem;font-weight:700;cursor:pointer;
    display:flex;flex-direction:column;align-items:center;gap:2px;
  }
  .speed-btn .speed-cost{font-size:.58rem;color:var(--ink-dim);font-weight:600;display:flex;align-items:center;gap:2px;}
  .speed-btn.active{background:var(--mote);color:#fff;border-color:var(--mote);}
  .speed-btn.active .speed-cost{color:#fff;}
  .speed-btn:disabled{opacity:1;cursor:not-allowed;}

  /* ---------- Ascend ---------- */
  .ascend-summary{display:flex;flex-direction:column;gap:10px;align-items:center;text-align:center;padding:18px 14px;}
  .ascend-breakdown{display:flex;gap:10px;width:100%;text-align:left;}
  .ab-col{flex:1;background:var(--bg-elev);border:1px solid var(--line);border-radius:10px;padding:10px 12px;}
  .ab-head{font-size:.64rem;text-transform:uppercase;letter-spacing:.06em;font-weight:700;margin-bottom:6px;}
  .ab-reset .ab-head{color:var(--danger);}
  .ab-keep .ab-head{color:var(--good);}
  .ab-col ul{margin:0;padding-left:15px;font-size:.71rem;color:var(--ink-dim);line-height:1.6;}
  .prism-preview{font-family:'IBM Plex Mono',monospace;font-size:1.6rem;font-weight:600;color:var(--prism);}
  .prism-calculation{width:100%;text-align:left;font-size:.8rem;color:var(--ink-dim);line-height:1.5;overflow-wrap:break-word;}
  .prism-calculation dl{margin:0;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:5px 10px;}
  .prism-calculation dt,.prism-calculation dd{margin:0;}
  .prism-calculation dd{text-align:right;color:var(--ink);}
  .prism-calculation p{margin:10px 0 0;}
  .big-btn{
    width:100%;padding:12px;border-radius:12px;border:none;cursor:pointer;
    font-weight:700;font-size:.92rem;letter-spacing:.01em;
    background:linear-gradient(135deg, var(--prism), color-mix(in srgb, var(--prism) 70%, var(--lumen)));
    color:#fff;box-shadow:var(--shadow);
  }
  .big-btn:disabled{background:var(--bg-elev-2);color:var(--ink-dim);cursor:not-allowed;box-shadow:none;border:1px solid var(--line);}

  /* ---------- Daily Quests ---------- */
  .daily-card{margin-bottom:14px;}
  .daily-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;}
  .daily-streak{font-size:.66rem;font-weight:700;color:var(--comet);background:var(--bg-elev);border:1px solid var(--line);border-radius:999px;padding:4px 10px;white-space:nowrap;}
  .quest-row{padding:10px 0;border-bottom:1px solid var(--line);}
  .quest-row:last-child{border-bottom:none;padding-bottom:0;}
  .quest-row:first-child{padding-top:0;}
  .quest-row-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:6px;}
  .quest-name{font-size:.8rem;font-weight:600;}
  .quest-reward{font-size:.7rem;color:var(--comet);font-weight:700;flex:none;display:flex;align-items:center;gap:3px;}
  .quest-bar-track{height:7px;border-radius:999px;background:var(--bg-elev);border:1px solid var(--line);overflow:hidden;}
  .quest-bar-fill{height:100%;width:0%;background:linear-gradient(90deg, var(--comet), color-mix(in srgb, var(--comet) 70%, var(--prism)));transition:width .3s linear;}
  .quest-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:6px;}
  .quest-progress-text{font-size:.68rem;color:var(--ink-dim);}
  .quest-claim-btn{flex:none;border-radius:8px;border:1px solid var(--good);background:var(--good);color:#08210f;font-weight:700;font-size:.68rem;padding:6px 14px;cursor:pointer;}
  .quest-claim-btn:disabled{opacity:1;cursor:not-allowed;background:var(--bg-elev);color:var(--ink-dim);border-color:var(--line);}
  .quest-claim-btn.done{background:var(--bg-elev);color:var(--good);border-color:var(--good);opacity:1;}

  /* ---------- Achievements ---------- */
  .ach-grid{display:grid;grid-template-columns:1fr;gap:8px;}
  .ach-card{display:flex;align-items:flex-start;gap:10px;}
  .ach-card .dot{flex:none;width:10px;height:10px;border-radius:50%;background:var(--line);margin-top:3px;}
  .ach-card.done .dot{background:var(--good);}
  .ach-card .info{flex:1;min-width:0;}
  .ach-card .name{font-size:.84rem;font-weight:600;}
  .ach-card.done .name{color:var(--ink-dim);text-decoration:line-through;}
  .ach-card .ach-unlock{font-size:.65rem;color:var(--prism);font-weight:600;margin-top:2px;}
  .ach-card.done .ach-unlock{color:var(--ink-dim);}
  .ach-card .reward{font-size:.72rem;color:var(--comet);font-weight:700;flex:none;}
  .ach-progress{font-size:.7rem;color:var(--ink-dim);font-weight:700;margin-top:3px;}
  .earned-effect{font-size:.74rem;line-height:1.5;color:var(--ink);margin-top:6px;overflow-wrap:anywhere;}
  .earned-effect strong{color:var(--prism);}
  .study-card .earned-effect strong{color:var(--mote);}
  .effect-note,.deed-requirement,.deed-scope{font-size:.7rem;line-height:1.5;color:var(--ink-dim);margin-top:4px;}
  .deed-scope{margin-top:6px;}
  .ach-card .reward{white-space:nowrap;}
  .shop-card{display:flex;align-items:center;gap:12px;margin-bottom:10px;}
  .shop-card .info{flex:1;}
  .shop-card .name{font-weight:700;font-size:.86rem;}
  .shop-card .desc{font-size:.72rem;color:var(--ink-dim);margin-top:2px;}
  .shop-card button{
    flex:none;border-radius:10px;border:1px solid var(--line);background:var(--bg-elev);
    padding:8px 12px;font-weight:700;font-size:.78rem;color:var(--comet);cursor:pointer;
  }
  .shop-card button:disabled{opacity:1;cursor:not-allowed;}
  .shop-card button.owned{color:var(--good);}
  .auto-ascend-card .name{font-size:1rem;font-weight:800;color:var(--ink);}
  .auto-ascend-row{display:flex;align-items:flex-end;gap:12px;margin-top:12px;}
  .auto-ascend-target-label{display:block;flex:1;min-width:0;font-size:.85rem;font-weight:700;color:var(--prism);}
  .auto-ascend-target{display:block;box-sizing:border-box;width:100%;min-width:0;min-height:48px;margin-top:6px;padding:10px;
    border:2px solid #b6a0e6;border-radius:10px;background:#141b31;color:#f1edff;font:inherit;font-size:1rem;color-scheme:dark;}
  .auto-ascend-target:focus,[data-autoascend-toggle]:focus,[data-autoascend-open]:focus{outline:3px solid #f6dc9b;outline-offset:3px;}
  input.auto-ascend-target{font-size:.8rem;}
  .auto-ascend-toggle{flex:none;min-width:76px;min-height:48px;padding:10px;border:2px solid #b9b8c9;border-radius:10px;
    background:#20273a;color:#f1edff;font:inherit;font-size:1.1rem;font-weight:800;cursor:pointer;}
  .auto-ascend-toggle[aria-pressed="true"]{border-color:#a4dfc2;background:#244538;color:#d9ffec;}
  .auto-ascend-card .desc{margin-top:10px;font-size:.8rem;line-height:1.5;color:var(--ink-dim);}
  .auto-ascend-error{color:#ffd4cc;font-size:.8rem;line-height:1.5;overflow-wrap:anywhere;}
  [data-autoascend-open],[data-autoascend-unlock]{min-width:44px;min-height:44px;}
  @media(max-width:360px){.auto-ascend-row{flex-wrap:wrap;}.auto-ascend-target-label{flex-basis:100%;}.auto-ascend-toggle{width:100%;}}
  .theme-card{display:flex;align-items:center;gap:12px;margin-bottom:10px;cursor:pointer;border-color:transparent;}
  .theme-card.active{border-color:var(--good);}
  .theme-card.locked-node{cursor:default;}
  .theme-swatch{flex:none;width:30px;height:30px;border-radius:50%;border:1px solid var(--line);}
  .theme-info{flex:1;min-width:0;}
  .theme-info .name{font-weight:700;font-size:.86rem;}
  .theme-info .desc{font-size:.72rem;color:var(--ink-dim);margin-top:2px;}
  .theme-active-tag{flex:none;font-size:.66rem;font-weight:700;color:var(--good);}

  /* ---------- About ---------- */
  .currency-grid{display:flex;flex-direction:column;gap:8px;margin-bottom:4px;}
  .currency-card{display:flex;gap:12px;align-items:flex-start;}
  .currency-card .shape{margin-top:2px;}
  .currency-card .cname{font-weight:700;font-size:.85rem;}
  .currency-card .cdesc{font-size:.76rem;color:var(--ink-dim);margin-top:2px;line-height:1.42;}
  .manifesto{display:flex;flex-direction:column;gap:10px;}
  .man-card .eyebrow{font-size:.66rem;text-transform:uppercase;letter-spacing:.08em;color:var(--prism);font-weight:700;margin-bottom:4px;}
  .man-card .title{font-weight:700;font-size:.88rem;margin-bottom:3px;}
  .man-card .body{font-size:.78rem;color:var(--ink-dim);line-height:1.45;}
  .fine-print{font-size:.7rem;color:var(--ink-dim);line-height:1.5;margin-top:14px;padding:0 2px;}
  .reset-btn{
    margin-top:14px;width:100%;min-height:44px;padding:11px;border-radius:12px;
    border:1px solid var(--danger);background:transparent;color:var(--danger);
    font-weight:700;font-size:.82rem;cursor:pointer;
  }
  .reset-confirm-row{margin-top:14px;}
  .reset-warning{font-size:.76rem;color:var(--danger);line-height:1.45;margin-bottom:10px;}
  .reset-confirm-actions{display:flex;gap:8px;}
  .reset-confirm-actions .reset-btn{flex:1;margin-top:0;}

  /* ---------- Tab bar ---------- */
  nav.tabbar{
    display:flex;
    background:color-mix(in srgb, var(--bg-elev) 94%, transparent);
    backdrop-filter:blur(10px);
    border-bottom:1px solid var(--line);
  }
  nav.tabbar button{
    flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;
    padding:8px 2px 7px;background:none;border:none;cursor:pointer;color:var(--ink-dim);
  }
  nav.tabbar button .ic{width:14px;height:14px;border:2px solid currentColor;}
  nav.tabbar button .lb{font-size:.56rem;font-weight:700;letter-spacing:.01em;}
  nav.tabbar button.active{color:var(--lumen);}
  nav.tabbar button.active .ic{background:var(--lumen);border-color:var(--lumen);}

  /* ---------- Modal / intro ---------- */
  .overlay{
    position:fixed;top:0;right:0;bottom:0;left:0;z-index:20;
    background:color-mix(in srgb, var(--bg) 80%, transparent);
    backdrop-filter:blur(6px);
    display:flex;align-items:center;justify-content:center;padding:24px;
  }
  .modal{
    max-width:380px;width:100%;background:var(--bg-elev);border:1px solid var(--line);
    border-radius:18px;padding:24px 22px;text-align:center;box-shadow:var(--shadow);
  }
  .modal h2{font-size:1.3rem;margin-bottom:8px;}
  .modal p{font-size:.85rem;color:var(--ink-dim);line-height:1.5;margin:0 0 16px;}
  .modal .primary-btn{
    width:100%;padding:11px;border-radius:12px;border:none;cursor:pointer;
    background:var(--lumen);color:#241900;font-weight:800;font-size:.88rem;
  }
  .modal .ghost-btn{
    width:100%;padding:9px;border-radius:12px;border:none;cursor:pointer;
    background:transparent;color:var(--ink-dim);font-weight:600;font-size:.78rem;margin-top:8px;
  }

  /* ---------- Settings / Encyclopedia ---------- */
  .settings-overlay{padding:12px;align-items:stretch;}
  .settings-modal{
    width:100%;max-width:520px;height:min(92vh,760px);margin:auto;
    background:var(--bg-elev);border:1px solid var(--line);border-radius:18px;
    box-shadow:var(--shadow);display:flex;flex-direction:column;overflow:hidden;
  }
  .settings-head{
    display:flex;align-items:center;gap:8px;padding:12px 12px 10px;
    border-bottom:1px solid var(--line);flex:none;
  }
  .settings-head h2{font-family:'Cinzel',serif;font-size:1rem;margin:0;flex:1;min-width:0;text-align:center;overflow-wrap:break-word;}
  .settings-icon-btn{
    width:34px;height:34px;border-radius:10px;border:1px solid var(--line);
    background:var(--bg-elev-2);color:var(--ink);font-size:1rem;cursor:pointer;
  }
  .settings-scroll{overflow-y:auto;padding:12px;overscroll-behavior:contain;}
  .settings-menu{display:flex;flex-direction:column;gap:8px;}
  .settings-row{
    width:100%;display:flex;align-items:center;gap:10px;text-align:left;
    padding:12px;border:1px solid var(--line);border-radius:12px;
    background:var(--bg-elev-2);color:var(--ink);cursor:pointer;
  }
  .settings-row .settings-row-main{flex:1;min-width:0;}
  .settings-row .settings-row-title{font-size:.82rem;font-weight:800;}
  .settings-row .settings-row-sub{font-size:.68rem;color:var(--ink-dim);margin-top:2px;line-height:1.35;}
  .settings-row .settings-chevron{font-size:1rem;color:var(--ink-dim);}
  .settings-section-title{
    font-size:.66rem;text-transform:uppercase;letter-spacing:.08em;color:var(--ink-dim);
    font-weight:800;margin:16px 2px 8px;
  }
  .ency-grid{display:flex;flex-direction:column;gap:8px;}
  .ency-card{
    border:1px solid var(--line);border-radius:12px;background:var(--bg-elev-2);
    padding:10px 11px;text-align:left;
  }
  .ency-top{display:flex;align-items:center;gap:9px;flex-wrap:wrap;}
  .ency-main{flex:1 1 120px;min-width:0;}
  .ency-name{font-size:.78rem;font-weight:800;overflow-wrap:break-word;}
  .ency-meta{font-size:.6875rem;color:var(--ink-dim);margin-top:1px;overflow-wrap:break-word;}
  .ency-desc{font-size:.69rem;color:var(--ink-dim);line-height:1.42;margin-top:6px;}
  .ency-status{flex:0 0 auto;font-size:.6rem;font-weight:800;padding:3px 7px;border-radius:999px;background:var(--bg-elev);color:var(--ink-dim);white-space:nowrap;}
  .ency-status.on{color:var(--good);}
  .settings-about{margin-top:10px;}
  .settings-about .man-card{margin-bottom:8px;}
  .save-backup-textarea{
    width:100%;min-height:150px;resize:vertical;border:1px solid var(--line);
    border-radius:12px;background:var(--bg-elev-2);color:var(--ink);
    padding:10px;font-family:monospace;font-size:.65rem;line-height:1.4;
  }
  .save-backup-actions{display:flex;gap:8px;margin-top:10px;}
  .save-backup-actions button{
    flex:1;padding:10px 8px;border-radius:10px;border:1px solid var(--line);
    background:var(--bg-elev-2);color:var(--ink);font-size:.72rem;font-weight:800;cursor:pointer;
  }
  .save-backup-actions .restore{border-color:var(--prism);color:var(--prism);}
  .save-backup-note{font-size:.7rem;color:var(--ink-dim);line-height:1.45;margin-bottom:10px;}

  /* ---------- xaribapps startup intro ---------- */
  .startup-intro{
    position:fixed;top:0;right:0;bottom:0;left:0;z-index:1000;display:none;align-items:center;justify-content:center;
    overflow:hidden;isolation:isolate;cursor:pointer;background:#05050b;color:#f7f5ff;
    opacity:1;visibility:visible;transition:opacity .42s ease,visibility .42s ease;
    -webkit-tap-highlight-color:transparent;
  }
  .startup-intro.is-visible{display:flex;}
  .startup-intro.is-leaving{opacity:0;visibility:hidden;pointer-events:none;}
  .startup-intro-bg{
    position:absolute;inset:-8%;z-index:-5;
    background:
      radial-gradient(circle at 50% 46%,rgba(126,83,238,.18) 0%,rgba(70,66,170,.08) 22%,transparent 49%),
      radial-gradient(circle at 20% 18%,rgba(77,154,255,.07),transparent 28%),
      radial-gradient(circle at 84% 76%,rgba(191,88,226,.065),transparent 31%),
      linear-gradient(180deg,#04050a 0%,#080812 55%,#05050b 100%);
    animation:startBgBreath 4.8s ease-in-out infinite;
  }
  .startup-intro-stars{
    position:absolute;inset:0;z-index:-4;opacity:.52;pointer-events:none;
    background-image:
      radial-gradient(circle at 14% 22%,rgba(255,255,255,.7) 0 1px,transparent 1.4px),
      radial-gradient(circle at 79% 17%,rgba(255,255,255,.45) 0 1px,transparent 1.5px),
      radial-gradient(circle at 30% 71%,rgba(206,197,255,.58) 0 1px,transparent 1.5px),
      radial-gradient(circle at 88% 68%,rgba(255,255,255,.55) 0 1px,transparent 1.5px),
      radial-gradient(circle at 57% 87%,rgba(175,207,255,.45) 0 1px,transparent 1.4px);
    animation:startStars 5s ease-in-out infinite alternate;
  }
  .startup-rift{
    position:absolute;left:50%;top:50%;z-index:-2;width:2px;height:2px;transform:translate(-50%,-50%);
    border-radius:999px;background:#fff;opacity:0;
    box-shadow:0 0 20px #fff,0 0 45px rgba(140,98,255,.8),0 0 90px rgba(77,119,255,.42);
  }
  .startup-rift::before,.startup-rift::after{
    content:'';position:absolute;left:50%;top:50%;width:1px;height:145px;transform-origin:center;
    background:linear-gradient(180deg,transparent,rgba(206,190,255,.18) 14%,rgba(255,255,255,.94) 50%,rgba(158,123,255,.2) 84%,transparent);
    filter:drop-shadow(0 0 8px rgba(170,133,255,.75));
  }
  .startup-rift::before{transform:translate(-50%,-50%) rotate(4deg);}
  .startup-rift::after{transform:translate(-50%,-50%) rotate(-5deg);}
  .startup-intro.phase-rift .startup-rift{animation:riftIgnite .56s cubic-bezier(.2,.8,.2,1) forwards;}
  .startup-content{position:relative;width:min(88vw,430px);height:230px;text-align:center;display:flex;align-items:center;justify-content:center;}
  .startup-brand,.startup-game{
    position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;
    opacity:0;transform:translateY(9px) scale(.985);pointer-events:none;
  }
  .startup-intro.phase-brand .startup-brand{animation:brandReveal 1.38s ease forwards;}
  .startup-intro.phase-game .startup-game{animation:gameReveal 1.45s cubic-bezier(.2,.78,.2,1) forwards;}
  .xaribapps-mark{
    position:relative;width:82px;height:82px;margin-bottom:18px;
    display:grid;place-items:center;
  }
  .xaribapps-ring{
    position:absolute;inset:0;border:1px solid rgba(185,163,255,.38);border-radius:50%;
    box-shadow:0 0 28px rgba(118,83,226,.18),inset 0 0 20px rgba(126,89,228,.08);
    animation:brandRingSpin 10s linear infinite;
  }
  .xaribapps-ring::before,.xaribapps-ring::after{
    content:'';position:absolute;border-radius:50%;inset:8px;border:1px solid rgba(119,159,255,.17);
  }
  .xaribapps-ring::after{inset:-5px;border-color:rgba(172,124,255,.11);border-style:dashed;}
  .xaribapps-x{
    position:relative;width:34px;height:34px;filter:drop-shadow(0 0 13px rgba(171,143,255,.55));
  }
  .xaribapps-x::before,.xaribapps-x::after{
    content:'';position:absolute;left:15px;top:-2px;width:4px;height:38px;border-radius:4px;
    background:linear-gradient(180deg,#fff,#bba8ff 55%,#6f85ef);
  }
  .xaribapps-x::before{transform:rotate(45deg);}
  .xaribapps-x::after{transform:rotate(-45deg);}
  .startup-brand-name{
    font-family:'Manrope',sans-serif;font-size:1rem;font-weight:800;letter-spacing:.17em;
    text-transform:lowercase;color:#f2efff;text-shadow:0 0 20px rgba(155,124,255,.2);
  }
  .startup-presents{
    margin-top:7px;font-size:.56rem;font-weight:700;letter-spacing:.34em;text-transform:uppercase;
    color:rgba(190,181,221,.62);
  }
  .startup-title-wrap{position:relative;padding:18px 8px;}
  .startup-game-mark{width:92px;height:92px;object-fit:contain;margin:0 auto -2px;filter:drop-shadow(0 0 24px rgba(229,180,89,.24)) drop-shadow(0 0 34px rgba(126,98,255,.18));}
  .startup-title-glow{
    position:absolute;left:50%;top:50%;width:260px;height:130px;transform:translate(-50%,-50%);
    background:radial-gradient(ellipse,rgba(132,90,240,.22),rgba(70,99,200,.08) 42%,transparent 70%);
    filter:blur(9px);animation:titleGlow 2.1s ease-in-out infinite;
  }
  .startup-title{
    position:relative;font-family:'Cinzel',serif;font-weight:700;font-size:clamp(2rem,8.2vw,3rem);
    line-height:1;letter-spacing:.16em;padding-left:.16em;color:#faf8ff;
    text-shadow:0 0 18px rgba(178,145,255,.27),0 0 42px rgba(88,118,255,.14);
  }
  .startup-title::after{
    content:'';position:absolute;left:8%;right:8%;bottom:-11px;height:1px;
    background:linear-gradient(90deg,transparent,rgba(176,143,255,.75),rgba(225,235,255,.9),rgba(119,143,255,.7),transparent);
    box-shadow:0 0 9px rgba(157,123,255,.52);
    transform:scaleX(0);animation:titleLine 1s .32s ease forwards;
  }
  .startup-tagline{
    position:relative;margin-top:28px;font-size:.57rem;font-weight:750;letter-spacing:.31em;
    text-transform:uppercase;color:rgba(199,196,221,.66);
  }
  .startup-skip{
    position:absolute;left:0;right:0;bottom:calc(17px + var(--safe-bottom));
    text-align:center;font-size:.55rem;font-weight:700;letter-spacing:.17em;text-transform:uppercase;
    color:rgba(202,198,220,.36);opacity:0;animation:skipIn .5s .75s ease forwards;
  }
  @keyframes startBgBreath{0%,100%{transform:scale(1);filter:brightness(.96);}50%{transform:scale(1.025);filter:brightness(1.08);}}
  @keyframes startStars{from{opacity:.35;transform:translateY(0);}to{opacity:.62;transform:translateY(-4px);}}
  @keyframes brandRingSpin{to{transform:rotate(360deg);}}
  @keyframes brandReveal{0%{opacity:0;transform:translateY(10px) scale(.97);}20%,73%{opacity:1;transform:none;}100%{opacity:0;transform:translateY(-5px) scale(1.015);}}
  @keyframes riftIgnite{0%{opacity:0;height:2px;transform:translate(-50%,-50%) scaleX(.5);}35%{opacity:1;height:5px;}100%{opacity:0;height:185px;transform:translate(-50%,-50%) scaleX(2.2);}}
  @keyframes gameReveal{0%{opacity:0;transform:scale(.93);filter:blur(4px);}20%,78%{opacity:1;transform:none;filter:none;}100%{opacity:1;transform:none;filter:none;}}
  @keyframes titleGlow{0%,100%{opacity:.72;transform:translate(-50%,-50%) scale(.93);}50%{opacity:1;transform:translate(-50%,-50%) scale(1.07);}}
  @keyframes titleLine{to{transform:scaleX(1);}}
  @keyframes skipIn{to{opacity:1;}}

  /* ---------- Tutorial ---------- */
  .tut-dots{display:flex;gap:6px;justify-content:center;margin-bottom:14px;}
  .tut-dot{width:6px;height:6px;border-radius:50%;background:var(--line);}
  .tut-dot.on{background:var(--lumen);}
  .tut-icon{width:44px;height:44px;margin:0 auto 14px;border-radius:12px;}

  /* ---------- Toast ---------- */
  .toast{
    position:fixed;left:50%;bottom:calc(var(--nav-height) + var(--safe-bottom) + 8px);transform:translate(-50%,8px);z-index:15;
    background:var(--ink);color:var(--bg);font-size:.76rem;font-weight:600;
    padding:8px 14px;border-radius:999px;opacity:0;pointer-events:none;
    transition:opacity .2s ease, transform .2s ease;width:max-content;max-width:min(460px,calc(100% - 32px));text-align:center;
    line-height:1.4;border-radius:12px;
  }
  .toast.show{opacity:1;transform:translate(-50%,0);}

  @media (prefers-reduced-motion: reduce){
    *{animation-duration:.001ms !important;transition-duration:.001ms !important;}
  }


  /* ============================================================
     Lumenfall visual system — mobile-first premium polish
     ============================================================ */
  :root{
    --panel-glass:color-mix(in srgb,var(--bg-elev) 88%,transparent);
    --panel-solid:color-mix(in srgb,var(--bg-elev-2) 92%,var(--bg-elev));
    --soft-line:color-mix(in srgb,var(--line) 72%,transparent);
    --deep-shadow:0 22px 60px -30px rgba(0,0,0,.82),0 4px 14px -8px rgba(0,0,0,.65);
    --inner-highlight:inset 0 1px 0 rgba(255,255,255,.055);
  }
  html{background:var(--bg);}
  body{
    background:
      radial-gradient(circle at 18% -8%,color-mix(in srgb,var(--prism) 11%,transparent),transparent 31rem),
      radial-gradient(circle at 86% 12%,color-mix(in srgb,var(--shard) 8%,transparent),transparent 26rem),
      var(--bg);
  }
  .shell{
    max-width:500px;
    background:linear-gradient(180deg,color-mix(in srgb,var(--bg-elev) 89%,transparent),color-mix(in srgb,var(--bg) 93%,transparent));
    backdrop-filter:blur(16px) saturate(1.08);
    border-color:var(--soft-line);
    box-shadow:0 0 70px -50px color-mix(in srgb,var(--prism) 55%,transparent);
  }
  .hud{
    padding:calc(10px + var(--safe-top)) 12px 9px;
    background:color-mix(in srgb,var(--bg-elev) 88%,transparent);
    border-color:var(--soft-line);
    backdrop-filter:blur(18px) saturate(1.18);
  }
  .hud .brand{
    font-size:1.08rem;letter-spacing:.045em;
    text-shadow:0 0 22px color-mix(in srgb,var(--prism) 24%,transparent);
  }
  .settings-btn,.settings-icon-btn{
    box-shadow:var(--inner-highlight);
    transition:transform .15s ease,border-color .15s ease,background .15s ease;
  }
  .settings-btn:active,.settings-icon-btn:active{transform:scale(.94);}
  .chip{
    background:linear-gradient(180deg,color-mix(in srgb,var(--bg-elev-2) 82%,transparent),color-mix(in srgb,var(--bg-elev) 86%,transparent));
    border-color:var(--soft-line);box-shadow:var(--inner-highlight);
    padding:5px 8px;
  }
  .chip .lbl{opacity:.82;font-size:.56rem;}
  .chip .val{font-weight:750;}

  nav.tabbar{
    background:color-mix(in srgb,var(--bg-elev) 90%,transparent);
    border-color:var(--soft-line);
    backdrop-filter:blur(18px) saturate(1.18);
    box-shadow:0 8px 24px -22px rgba(0,0,0,.7);
  }
  nav.tabbar button{
    position:relative;min-height:50px;padding:8px 2px 7px;
    transition:color .18s ease,transform .18s ease;
  }
  nav.tabbar button:active{transform:translateY(1px) scale(.97);}
  nav.tabbar button::after{
    content:'';position:absolute;left:28%;right:28%;bottom:2px;height:2px;border-radius:2px;
    background:currentColor;opacity:0;transform:scaleX(.4);transition:.18s ease;
  }
  nav.tabbar button.active::after{opacity:.8;transform:scaleX(1);}
  nav.tabbar button.active .ic{box-shadow:0 0 16px color-mix(in srgb,var(--lumen) 48%,transparent);}

  main{
    padding:16px 12px calc(28px + var(--safe-bottom));
  }
  .tab-panel.active{animation:panelIn .22s ease-out;}
  @keyframes panelIn{from{opacity:0;transform:translateY(7px) scale(.995);}to{opacity:1;transform:none;}}
  .card{
    background:
      linear-gradient(145deg,color-mix(in srgb,var(--bg-elev-2) 92%,transparent),color-mix(in srgb,var(--bg-elev) 96%,transparent));
    border-color:var(--soft-line);
    box-shadow:var(--deep-shadow),var(--inner-highlight);
    border-radius:16px;
  }
  .section-label{
    display:flex;align-items:center;gap:8px;
    font-weight:850;letter-spacing:.105em;font-size:.66rem;
  }
  .section-label::after{
    content:'';height:1px;flex:1;
    background:linear-gradient(90deg,var(--soft-line),transparent);
  }
  .section-sub{line-height:1.48;}

  /* Rift */
  #tab-battle .stage{
    position:relative;overflow:hidden;isolation:isolate;
    padding:17px 14px 15px;
    background:
      radial-gradient(circle at 50% 26%,color-mix(in srgb,var(--zone-accent,var(--prism)) 14%,transparent),transparent 42%),
      linear-gradient(160deg,color-mix(in srgb,var(--bg-elev-2) 92%,transparent),color-mix(in srgb,var(--bg-elev) 96%,transparent));
    transition:border-color .35s ease,box-shadow .35s ease,background .35s ease;
  }
  #tab-battle .stage::before{
    content:'';position:absolute;z-index:-1;inset:-35% -30% 38%;
    background:
      radial-gradient(circle at 50% 50%,color-mix(in srgb,var(--zone-accent,var(--prism)) 16%,transparent),transparent 56%),
      repeating-radial-gradient(circle at 50% 80%,transparent 0 19px,color-mix(in srgb,var(--zone-accent,var(--prism)) 5%,transparent) 20px 21px);
    opacity:.82;pointer-events:none;transform:rotate(-6deg);
  }
  #tab-battle .stage::after{
    content:'';position:absolute;z-index:-1;inset:0;pointer-events:none;
    background:
      radial-gradient(circle at 12% 22%,rgba(255,255,255,.18) 0 1px,transparent 1.6px),
      radial-gradient(circle at 86% 38%,rgba(255,255,255,.12) 0 1px,transparent 1.5px),
      radial-gradient(circle at 23% 78%,rgba(255,255,255,.10) 0 1px,transparent 1.4px),
      radial-gradient(circle at 76% 72%,rgba(255,255,255,.14) 0 1px,transparent 1.5px);
    opacity:.65;
  }
  .depth-label{
    color:var(--ink);font-size:.8rem;line-height:1.25;
    text-shadow:0 1px 14px color-mix(in srgb,var(--zone-accent,var(--prism)) 16%,transparent);
  }
  .depth-label .region-label{font-size:.57rem;margin-top:4px;font-weight:850;opacity:.95;}
  .enemy-name{font-size:1.08rem;letter-spacing:.015em;text-shadow:0 0 18px color-mix(in srgb,var(--zone-accent,var(--prism)) 24%,transparent);}
  .rift-mode-row{
    padding:3px;background:color-mix(in srgb,var(--bg-elev) 70%,transparent);
    border:1px solid var(--soft-line);border-radius:12px;gap:3px;
  }
  .rift-mode-btn{
    border:none;border-radius:9px;background:transparent;padding:8px 9px;
    transition:background .18s ease,color .18s ease,box-shadow .18s ease;
  }
  .rift-mode-btn.active{
    background:linear-gradient(135deg,color-mix(in srgb,var(--lumen) 17%,var(--bg-elev)),color-mix(in srgb,var(--prism) 9%,var(--bg-elev)));
    box-shadow:0 5px 16px -12px color-mix(in srgb,var(--lumen) 70%,transparent),var(--inner-highlight);
  }
  .rift-mode-note{font-size:.6875rem;opacity:.88;}
  .battle-row{gap:11px;align-items:center;margin:1px 0 3px;}
  .party-col{width:62px;gap:6px;}
  .hero-chip{
    background:linear-gradient(160deg,color-mix(in srgb,var(--bg-elev) 91%,transparent),color-mix(in srgb,var(--bg-elev-2) 86%,transparent));
    border-color:var(--soft-line);border-radius:11px;padding:6px 2px 7px;
    box-shadow:var(--inner-highlight),0 8px 18px -18px rgba(0,0,0,.7);
  }
  .hero-chip .shape{filter:drop-shadow(0 0 7px currentColor);}
  .chip-bar-track{height:4px;background:color-mix(in srgb,var(--line) 65%,transparent);}
  .chip-bar-fill{box-shadow:0 0 7px currentColor;}
  .chip-label{font-weight:850;}
  .chip-flash{
    padding:2px 5px;border-radius:999px;
    background:color-mix(in srgb,var(--bg-elev) 88%,transparent);
    border:1px solid var(--soft-line);box-shadow:var(--deep-shadow);
  }
  .enemy-stage-wrap{gap:8px;}
  .enemy-stage{
    width:154px;height:154px;isolation:isolate;
    transition:filter .25s ease,transform .18s ease;
  }
  .enemy-stage::before{
    inset:-24px;
    background:
      radial-gradient(circle,color-mix(in srgb,var(--theme-accent,var(--zone-accent,var(--prism))) 42%,transparent) 0%,transparent 64%);
    filter:blur(2px);animation:riftAura 3.8s ease-in-out infinite;
  }
  .enemy-stage::after{
    content:'';position:absolute;z-index:-1;width:132px;height:132px;border-radius:50%;
    border:1px solid color-mix(in srgb,var(--theme-accent,var(--zone-accent,var(--prism))) 26%,transparent);
    box-shadow:inset 0 0 26px color-mix(in srgb,var(--theme-accent,var(--zone-accent,var(--prism))) 8%,transparent);
    animation:riftOrbit 14s linear infinite;pointer-events:none;
  }
  @keyframes riftAura{0%,100%{transform:scale(.96);opacity:.7;}50%{transform:scale(1.06);opacity:1;}}
  @keyframes riftOrbit{to{transform:rotate(360deg);}}
  .enemy-glyph{
    position:relative;width:98px;height:98px;
    background:
      radial-gradient(circle at 32% 27%,rgba(255,255,255,.18),transparent 21%),
      linear-gradient(155deg,color-mix(in srgb,var(--danger) 92%,#fff 8%),color-mix(in srgb,var(--danger) 55%,#190f35));
    box-shadow:
      0 0 28px -2px color-mix(in srgb,var(--danger) 47%,transparent),
      inset 8px 8px 18px rgba(255,255,255,.07),
      inset -12px -12px 22px rgba(0,0,0,.18);
    animation:enemyBreathe 2.9s ease-in-out infinite;
  }
  .enemy-glyph::before,.enemy-glyph::after{
    content:'';position:absolute;pointer-events:none;
  }
  .enemy-glyph::before{
    inset:17%;border-radius:inherit;
    border:1px solid rgba(255,255,255,.16);
    transform:rotate(18deg);opacity:.75;
  }
  .enemy-glyph::after{
    width:10px;height:10px;border-radius:50%;left:50%;top:50%;transform:translate(-50%,-50%);
    background:rgba(255,255,255,.7);box-shadow:0 0 14px rgba(255,255,255,.55);
  }
  @keyframes enemyBreathe{0%,100%{transform:scale(.98) rotate(-1deg);}50%{transform:scale(1.025) rotate(1deg);}}
  .enemy-glyph.boss{
    width:112px;height:112px;
    box-shadow:0 0 38px 2px color-mix(in srgb,var(--danger) 52%,transparent),inset 0 0 24px rgba(255,255,255,.08);
    animation:bossBreathe 2.2s ease-in-out infinite;
  }
  @keyframes bossBreathe{0%,100%{transform:scale(.98);}50%{transform:scale(1.04);}}
  .enemy-stage.trait-regrowth .enemy-glyph{
    background:radial-gradient(circle at 50% 46%,rgba(181,255,177,.23),transparent 24%),linear-gradient(155deg,#4ea867,#173b31 72%);
    box-shadow:0 0 42px 3px rgba(86,214,124,.28),inset 0 0 24px rgba(214,255,221,.12);
  }
  .enemy-stage.trait-regrowth::after{border-color:color-mix(in srgb,var(--good) 45%,transparent);}
  .enemy-stage.trait-fractured .enemy-glyph{
    background:
      linear-gradient(45deg,transparent 45%,rgba(222,205,255,.28) 47% 51%,transparent 53%),
      linear-gradient(135deg,transparent 34%,rgba(196,164,255,.23) 36% 39%,transparent 41%),
      linear-gradient(155deg,#8155cf,#241543 72%);
    box-shadow:0 0 45px 4px color-mix(in srgb,var(--prism) 48%,transparent),inset 0 0 25px rgba(225,209,255,.14);
  }
  .enemy-stage.trait-guardian .enemy-glyph{
    background:radial-gradient(circle at 50% 46%,rgba(255,228,151,.28),transparent 25%),linear-gradient(155deg,#c9892d,#542214 75%);
    box-shadow:0 0 45px 4px color-mix(in srgb,var(--lumen) 52%,transparent),inset 0 0 25px rgba(255,236,184,.13);
  }
  .stage.boss-ready{border-color:color-mix(in srgb,var(--good) 46%,var(--line));}
  .stage.boss-wall{border-color:color-mix(in srgb,var(--danger) 43%,var(--line));}
  .stage.boss-wall .enemy-stage{filter:saturate(.9);}
  .enemy-glyph.luminous{
    filter:brightness(1.2) saturate(1.18);
    box-shadow:0 0 54px 10px color-mix(in srgb,var(--mote) 52%,transparent),inset 0 0 22px rgba(255,255,255,.16);
  }
  .enemy-stage.hit{transform:scale(.98);}
  .enemy-stage.hit .enemy-glyph{transform:scale(.86) rotate(-3deg);filter:brightness(1.22);}
  .hp-bar-track{height:10px;background:color-mix(in srgb,var(--bg) 62%,var(--bg-elev));border-color:var(--soft-line);}
  .hp-bar-fill{
    background:linear-gradient(90deg,color-mix(in srgb,var(--danger) 88%,#70233b),#ff7d73);
    box-shadow:0 0 14px color-mix(in srgb,var(--danger) 35%,transparent);
  }
  .boss-regen-tag{
    border:1px solid color-mix(in srgb,var(--good) 27%,var(--line));
    background:color-mix(in srgb,var(--good) 7%,var(--bg-elev));
    border-radius:10px;padding:7px 8px;line-height:1.35;margin-top:6px;
  }
  .boss-regen-tag.insufficient{
    background:color-mix(in srgb,var(--danger) 7%,var(--bg-elev));
    border-color:color-mix(in srgb,var(--danger) 30%,var(--line));
  }
  .buff-indicator{
    align-self:center;padding:5px 9px;border-radius:999px;
    border:1px solid color-mix(in srgb,var(--good) 30%,var(--line));
    background:color-mix(in srgb,var(--good) 8%,var(--bg-elev));
  }
  .bond-summary{font-size:.6875rem;opacity:.9;}
  .tap-hint{font-size:.65rem;line-height:1.42;opacity:.82;}
  .stat-box{
    background:linear-gradient(160deg,color-mix(in srgb,var(--bg-elev) 82%,transparent),color-mix(in srgb,var(--bg-elev-2) 74%,transparent));
    border-color:var(--soft-line);box-shadow:var(--inner-highlight);
  }
  .stat-box .v{font-size:.93rem;}
  .float-num{
    font-size:.86rem;font-weight:850;text-shadow:0 2px 10px rgba(0,0,0,.25);
    animation:floatUpVisual .7s cubic-bezier(.2,.8,.25,1) forwards;
  }
  @keyframes floatUpVisual{0%{opacity:1;transform:translate(-50%,4px) scale(.92);}55%{opacity:1;}100%{opacity:0;transform:translate(-50%,-50px) scale(1.08);}}

  /* Wisps */
  .bond-card{
    position:relative;overflow:hidden;
    background:
      radial-gradient(circle at 95% 0%,color-mix(in srgb,var(--prism) 10%,transparent),transparent 38%),
      linear-gradient(145deg,color-mix(in srgb,var(--bg-elev-2) 94%,transparent),color-mix(in srgb,var(--bg-elev) 96%,transparent));
  }
  .bond-row{border-color:var(--soft-line);background:color-mix(in srgb,var(--bg-elev) 78%,transparent);}
  .bond-row.active{
    border-color:color-mix(in srgb,var(--good) 43%,var(--line));
    box-shadow:inset 3px 0 0 color-mix(in srgb,var(--good) 70%,transparent);
  }
  .hero-card{
    position:relative;overflow:hidden;padding:13px;
    transition:border-color .2s ease,transform .16s ease,box-shadow .2s ease;
  }
  .hero-card::before{
    content:'';position:absolute;left:0;top:0;bottom:0;width:3px;
    background:var(--rarity-color,var(--line));opacity:.78;
  }
  .hero-card::after{
    content:'';position:absolute;right:-44px;top:-58px;width:120px;height:120px;border-radius:50%;
    background:radial-gradient(circle,color-mix(in srgb,var(--wisp-color,var(--prism)) 13%,transparent),transparent 67%);
    pointer-events:none;
  }
  .hero-card.active-wisp{
    border-color:color-mix(in srgb,var(--wisp-color,var(--good)) 38%,var(--line));
    box-shadow:var(--deep-shadow),var(--inner-highlight),0 0 24px -20px var(--wisp-color,var(--good));
  }
  .hero-card.has-ultimate::before{width:4px;box-shadow:0 0 11px var(--sigil);}
  .hero-card.rarity-4,.hero-card.rarity-5{
    background:
      radial-gradient(circle at 93% 3%,color-mix(in srgb,var(--rarity-color) 11%,transparent),transparent 35%),
      linear-gradient(145deg,color-mix(in srgb,var(--bg-elev-2) 92%,transparent),color-mix(in srgb,var(--bg-elev) 96%,transparent));
  }
  .hero-top .shape{filter:drop-shadow(0 0 8px color-mix(in srgb,var(--wisp-color,currentColor) 42%,transparent));}
  .hero-id .name{font-size:.92rem;font-weight:850;}
  .class-tag{font-size:.6rem;letter-spacing:.065em;}
  .active-toggle{
    padding:6px 10px;border-color:var(--soft-line);box-shadow:var(--inner-highlight);
  }
  .active-toggle.is-active{
    color:var(--good);background:color-mix(in srgb,var(--good) 10%,var(--bg-elev));
    border-color:color-mix(in srgb,var(--good) 34%,var(--line));
    box-shadow:0 0 16px -12px var(--good);
  }
  .hero-stats{
    padding:7px 9px;border-radius:9px;
    background:color-mix(in srgb,var(--bg-elev) 62%,transparent);
    border:1px solid var(--soft-line);line-height:1.45;
  }
  .hero-ability{
    padding:8px 9px;margin:7px 0 8px;border-radius:9px;
    background:color-mix(in srgb,var(--wisp-color,var(--prism)) 5%,var(--bg-elev));
    border:1px solid color-mix(in srgb,var(--wisp-color,var(--prism)) 17%,var(--line));
