  /* Forge */
  #tab-forge .node-card{
    border-left:3px solid color-mix(in srgb,var(--shard) 70%,transparent);
    background:
      radial-gradient(circle at 100% 0%,color-mix(in srgb,var(--shard) 6%,transparent),transparent 35%),
