    box-shadow:0 5px 14px -10px var(--shard);
  }
  .study-card{
    position:relative;overflow:hidden;
    background:
      radial-gradient(circle at 96% 0%,color-mix(in srgb,var(--mote) 10%,transparent),transparent 36%),
