  /* Fixed HUD tracks and bounded Rift chrome protect the interaction region. */
  .hud{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;padding:calc(4px + var(--safe-top)) 10px 4px;}
  .hud-title-row{grid-column:1/-1;height:44px;margin:0;}
  .settings-btn{width:44px;height:44px;}
  .hud .chip{display:grid;grid-template-columns:12px minmax(0,1fr);grid-template-rows:12px 14px;column-gap:4px;row-gap:0;height:34px;padding:3px 7px;}
  .hud .chip .glyph-icon{width:11px;height:11px;}
  .hud .chip .lbl{font-size:10px;line-height:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  .hud .chip .val{grid-column:1/-1;font-size:12px;line-height:14px;min-width:0;}
  nav.tabbar button{min-width:44px;height:var(--nav-height);min-height:var(--nav-height);padding:4px 2px;}
  nav.tabbar .lb{font-size:10px;}
  main.rift-scroll-locked{padding:6px 10px;}
  .shell:has(#tab-battle.active) .hud .brand{text-transform:uppercase;font-family:'Cinzel',serif;}
  .shell:has(#tab-battle.active) .hud{gap:4px;padding:calc(4px + var(--safe-top)) 10px 4px;background:#171930;}
  .shell:has(#tab-battle.active) .hud .chip{display:flex;align-items:center;gap:3px;height:24px;padding:2px 3px;border-color:#343950;background:linear-gradient(180deg,#222540,#191d34);box-shadow:inset 0 1px 0 #ffffff0a;}
  .shell:has(#tab-battle.active) .hud .chip .val{flex:none;margin-left:auto;font-size:10px;line-height:16px;white-space:nowrap;}
  #tab-battle.active{animation-name:riftPanelIn;}
  @keyframes riftPanelIn{from{opacity:0;}to{opacity:1;}}
  #tab-battle .stage{--ink:#f0effb;--ink-dim:#b5b4cb;--bg-elev:#13192d;--bg-elev-2:#1c2339;--line:#30364d;--danger:#ff7b92;--lumen:#e7c67e;--prism:#bd9bef;--shard:#82d2ec;--mote:#ffb4d5;--good:#9ed9b1;padding:8px 10px;gap:4px!important;background:radial-gradient(ellipse at 50% 38%,var(--land-far) 0,#11182d 47%,#0b1121 100%)!important;}
  .rift-heading{display:flex;flex-direction:column;align-items:stretch;gap:4px;flex:none;position:relative;z-index:2;}
  .stage .depth-label{min-width:0;font-size:18px;line-height:23px;letter-spacing:.08em;text-align:center;}
  .stage .depth-label .boss-tag{font:inherit;color:#ff849e;}
  .stage .depth-label .region-label{font-size:10px;line-height:14px;letter-spacing:.16em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  .stage .rift-heading .rift-mode-row{height:46px;min-height:46px;margin:0;gap:3px;padding:1px;background:#090f20a6;border-radius:12px;}
  .stage .rift-mode-btn{min-width:44px;min-height:44px;font-size:12px;padding:3px 6px;letter-spacing:.09em;white-space:nowrap;}
  /* F07: the hint body has the same reserved space when hidden or scrollable. */
  #rift-guidance-slot{position:relative;display:flex;height:46px;flex:none;margin:0 10px;color:#f0effb;background:#141d30;border:1px solid #52617e;border-radius:11px;box-sizing:border-box;box-shadow:0 3px 10px #050a1666;}
  /* Paint behind the inset strip into the arena gap without changing its tracks. */
  #rift-guidance-slot::before{content:'';position:absolute;top:-1px;right:-11px;bottom:-7px;left:-11px;z-index:-1;pointer-events:none;background:linear-gradient(180deg,#171930 0%,#0d0f1f 100%);}
  #rift-guidance-slot[hidden],#rift-objective-row[hidden]{display:none;}
#rift-hints-toggle{display:block;flex:none;width:auto;max-width:70%;min-width:44px;height:44px;min-height:44px;padding:2px;border:0;border-right:1px solid #52617e;border-radius:10px 0 0 10px;background:#1c2339;color:#f0effb;font:inherit;font-size:.875rem;line-height:1.1;font-weight:700;white-space:nowrap;cursor:pointer;}
/* Reserve both labels' intrinsic width without consuming hint space in ems. */
#rift-hints-toggle::before{content:'Show hints\A Hide hints';display:block;height:0;overflow:hidden;visibility:hidden;white-space:pre;}
  #rift-objective-row{flex:1;min-width:0;height:44px;min-height:0;overflow-y:auto;overflow-x:hidden;border-radius:0 10px 10px 0;}
  #rift-guidance-slot .rift-objective{min-width:0;min-height:44px;height:auto;padding:4px 2px;grid-template-columns:minmax(0,1fr) auto;gap:1px;border:0;border-radius:0;background:transparent;box-shadow:none;overflow:visible;}
  #rift-guidance-slot .objective-kind{display:none;}
  #rift-guidance-slot .objective-copy strong,#rift-guidance-slot .objective-copy small{white-space:normal;overflow:visible;text-overflow:clip;overflow-wrap:break-word;}
  #rift-guidance-slot .objective-copy strong{font-size:.875rem;line-height:1.2;}
  #rift-guidance-slot .objective-copy small{font-size:.75rem;line-height:1.2;color:#b5b4cb;}
  #rift-guidance-slot .objective-arrow{color:#b5b4cb;}
  #rift-hints-toggle:focus,#rift-objective-row:focus,#rift-guidance-slot .rift-objective:focus{outline:2px solid #e7c67e;outline-offset:-3px;}
  .late-power-guide[hidden]{display:none;}
  .late-power-guide{overflow-wrap:anywhere;}
  .late-power-guide h3{margin:0 0 8px;font-size:1rem;}
  .late-power-guide p{margin:8px 0;}
  .late-power-guide button{min-width:44px;min-height:44px;max-width:100%;white-space:normal;}
  .stage .objective-kind{display:block;font-size:9px;line-height:12px;letter-spacing:.05em;padding:3px 5px;white-space:nowrap;}
  .stage .objective-copy strong{font-size:12px;line-height:16px;}
  .stage .objective-copy small{font-size:11px;line-height:14px;}
  .stage .enemy-name{position:absolute;top:0;left:4px;right:4px;font-size:15px;line-height:22px;margin:0;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;pointer-events:none;}
  .stage .battle-row{min-height:0;flex-direction:column;gap:5px;margin:0 -4px;}
  .stage .enemy-stage-wrap{position:relative;min-height:120px;gap:0;}
  .stage .enemy-stage{min-height:120px;overflow:visible;container-type:size;}
  .guardian-label{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;pointer-events:none;}
  .stage .hp-wrap{flex:none;align-self:center;width:90%;max-width:340px;height:24px;}
  .stage .hp-text{font-size:11px;line-height:14px;margin-top:3px;white-space:nowrap;}
  .stage .stat-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;height:44px;min-height:44px;}
  .stage .stat-box{padding:3px 8px;min-width:0;}
  .stage .stat-box .k{font-size:10px;line-height:14px;letter-spacing:.03em;}
  .stage .stat-box .v{font-size:14px;line-height:22px;margin-top:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  /* Status follows the arena and the independent Wisp cards. */
  .stage .buff-indicator{position:relative;z-index:2;align-self:center;max-width:100%;border:1px solid #91c7b647;border-radius:999px;background:#91c7b614;font-size:11px;line-height:14px;color:#a5dabc;margin:0;padding:4px 9px;text-align:center;}
  .stage .buff-indicator strong{display:inline;font-size:11px;line-height:14px;color:var(--ink);}
  .stage .buff-indicator.is-active strong{color:#a5e9bc;}
  .stage .bond-summary{position:relative;z-index:2;font-size:11px;line-height:14px;color:#c3c9df;opacity:1;text-align:center;margin:0;}
  .lab-capacity-badge{position:absolute;top:2px;right:8px;min-width:16px;padding:0 3px;border:1px solid #a5e9bc;border-radius:8px;background:#18352d;color:#d4ffe5;font:700 10px/14px 'Manrope',sans-serif;pointer-events:none;}
  .lab-capacity-badge[hidden]{display:none;}
  .formation-preset-card{padding:10px;margin-bottom:10px;}
  .formation-preset-head{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:8px;}
  .formation-preset-title{font-size:.82rem;font-weight:800;}
  .formation-preset-state{font-size:11px;color:var(--ink-dim);font-weight:700;}
  .formation-preset-grid{display:flex;flex-wrap:wrap;gap:6px;}
  .formation-preset-slot{display:grid;flex:1 1 0;min-width:min-content;}
  .formation-preset-btn,.auto-empower-all{border:1px solid var(--line);border-radius:10px;background:var(--bg-elev);color:var(--ink);font:700 12px 'Manrope',sans-serif;min-width:44px;min-height:52px;padding:8px 4px;}
  .formation-preset-btn[aria-pressed="true"]{border-color:var(--lumen);background:color-mix(in srgb,var(--lumen) 12%,var(--bg-elev));}
  .formation-preset-btn span{display:block;font-size:10px;line-height:1.4;color:var(--ink-dim);font-weight:500;}
  #tab-spirits .active-toggle{min-width:48px;min-height:48px;}
  .auto-empower-all{width:100%;min-height:44px;margin-top:8px;}
  .study-slot-summary{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:12px;}
  .study-slot-summary strong{display:block;font-size:15px;}
  .study-slot-summary span{display:block;font-size:12px;color:var(--ink-dim);margin-top:3px;}
  .study-slot-summary.has-open span{color:var(--good);}
  .study-choose-btn{min-height:44px;padding:8px 12px;border:1px solid var(--mote);border-radius:10px;background:var(--bg-elev);color:var(--ink);font:700 12px 'Manrope',sans-serif;}
  #study-list .study-running{border-left:3px solid var(--mote);padding:10px 12px;margin-bottom:10px;}
  #study-list .study-running .name{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:13px;}
  #study-list .study-time{font-size:13px;font-weight:700;color:var(--ink);margin:6px 0;}
  .study-running-label{font-size:11px;color:var(--mote);font-weight:700;margin-bottom:4px;}
  .study-inspection>summary{min-height:44px;padding:12px 0;font-size:12px;cursor:pointer;color:var(--ink-dim);}
  .study-inspection .speed-row{margin-top:8px;}
  .study-choices-title{font-size:13px;font-weight:800;margin:16px 0 8px;}
  .study-choose-btn:focus-visible,.study-inspection>summary:focus-visible,.study-choices-title:focus-visible{outline:2px solid var(--lumen);outline-offset:2px;}
  /* P2-02B Part 1: task order matches DOM/keyboard order. */
  .formation-lineup{display:flex;gap:8px;flex-wrap:wrap;margin:6px 0 10px;}
  .formation-member{display:flex;align-items:center;gap:3px;font-size:11px;color:var(--ink);}
  .formation-member .wisp-portrait{width:24px;height:24px;flex:none;}
  #tab-spirits .formation-preset-card{margin-bottom:12px;}
  #tab-spirits .hero-grid{display:flex;flex-direction:column;gap:10px;}
  .roster-group-label{font-size:12px;font-weight:800;color:var(--ink-dim);margin:2px 0;}
  #tab-spirits .hero-card{margin:0;padding:12px;}
  #tab-spirits .hero-top{margin-bottom:6px;flex-wrap:wrap;}
  #tab-spirits .hero-id{min-width:min-content;}
  .wisp-empower-action{width:100%;min-width:44px;min-height:44px;margin:8px 0;display:flex;flex-direction:row;justify-content:space-between;align-items:center;gap:8px;flex-wrap:nowrap;white-space:nowrap;}
  .wisp-empower-action:not(:disabled){border-color:var(--lumen);color:var(--lumen);}
  .wisp-progression{border-top:1px solid var(--line);margin-top:4px;}
  .wisp-progression>summary,.wisp-progression-title{min-height:44px;padding:12px 0;margin:0;font-size:.75rem;color:var(--ink-dim);font-weight:700;}
  .wisp-progression>summary{cursor:pointer;}
  .wisp-progression>summary:focus-visible{outline:2px solid var(--lumen);outline-offset:2px;}
  .formation-help{margin:12px 0;animation:none!important;transition:none!important;}
  .formation-help>summary{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:4px 12px;width:100%;min-height:44px;cursor:pointer;padding:8px 12px;border:1px solid var(--line);border-radius:8px;background:var(--bg-elev);color:var(--ink);font-size:1rem;line-height:1.4;list-style:none;}
  .formation-help>summary::-webkit-details-marker{display:none;}
  .formation-help .formation-help-collapse,.formation-help[open] .formation-help-expand{display:none;}
  .formation-help[open] .formation-help-collapse{display:inline;}
  .formation-help>.section-sub{margin-top:12px;}
  .formation-best-now{margin:12px 0;}
  .formation-best-now button{width:100%;min-height:44px;white-space:normal;}
