  .stage .rift-mode-btn .control-state{font-size:10px;line-height:12px;}
  #boss-combat{flex:none;align-self:center;width:90%;max-width:340px;padding:3px 7px;border:1px solid #ed8aa744;border-radius:11px;background:#131c2fee;color:#f3bbc8;font-size:11px;line-height:13px;text-align:center;}
  #boss-combat[hidden]{display:none;}
  #boss-combat strong{display:inline;color:#f3bbc8;font-size:11px;line-height:13px;}
  .boss-net{display:inline;color:#d0d8ee;}.boss-net::before{content:" · ";}
  .boss-net.positive{color:#a5e9bc;}.boss-net.negative{color:#ffb3be;}
  #tab-battle .stage .enemy-stage{padding:0;}
  #tab-battle .stage .enemy-glyph{max-height:calc(100% - 26px);width:auto;height:clamp(100px,24vh,220px);max-width:80%;margin-top:14px;}
  #tab-battle .stage .enemy-glyph.boss{width:auto;}
  #rift-party{position:relative;display:flex;flex:none;justify-content:center;gap:6px;height:61px;z-index:4;pointer-events:none;}
  .rift-wisp{position:relative;width:calc((100% - 24px)/5);max-width:58px;min-width:0;height:61px;border:1px solid color-mix(in srgb,var(--wisp-color) 30%,#29334e);border-radius:11px;background:linear-gradient(155deg,#263049e0,#101a2eed);display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:27px 3px 13px 14px;gap:0;align-items:center;justify-items:center;padding:1px 3px;box-shadow:inset 0 1px 0 #ffffff0c,0 2px 9px #0004;}
  #rift-party .wisp-portrait{width:27px;height:27px;grid-column:1;grid-row:1;filter:drop-shadow(0 0 5px color-mix(in srgb,var(--wisp-color) 22%,transparent));}
  .rift-wisp-bonds{position:absolute;top:1px;left:2px;display:flex;flex-direction:column;gap:0;pointer-events:none;}
  .rift-wisp-bonds .rift-bond-mark{font-size:8px;line-height:8px;margin:0;}
  .rift-wisp-name{grid-column:1;grid-row:3;font-size:10px;line-height:13px;color:#c7cbe0;text-align:center;white-space:nowrap;}
  .rift-wisp-power{grid-column:1;grid-row:4;font:10px/14px 'IBM Plex Mono',monospace;color:#f0effb;text-align:center;}
  .rift-wisp-state{position:absolute;top:2px;right:2px;padding:0 2px;border-radius:3px;background:#0b132ade;font:10px/12px 'IBM Plex Mono',monospace;color:#c4cfe4;text-align:center;}
  .rift-wisp-state:empty{display:none;}
  .rift-charge{grid-column:1;grid-row:2;height:3px;border-radius:3px;background:#030818;overflow:hidden;width:100%;}
  .rift-charge>span{display:block;height:100%;background:var(--wisp-color);box-shadow:0 0 8px var(--wisp-color);transition:width .1s linear;}
  .rift-wisp.unpowered{border-style:dashed;}.rift-wisp.unpowered .rift-wisp-state{color:#c4cfe4;}
  .rift-wisp.is-casting{border-color:#fff;box-shadow:0 0 14px color-mix(in srgb,var(--wisp-color) 65%,transparent);}
  .rift-wisp.is-casting .rift-wisp-state{color:#fff;}
  .rift-wisp[data-bond]{border-color:var(--bond-color);box-shadow:inset 0 2px var(--bond-color),0 2px 9px #0006;}
  .rift-wisp.bond-start{margin-right:-4px;}
  .rift-wisp.bond-end{border-radius:11px;}
  .rift-wisp.bond-end:not(:last-child){margin-right:4px;}
  .rift-bond-mark{color:var(--bond-color);font-size:9px;line-height:12px;margin-right:2px;}
  .rift-wisp[data-bond] .rift-charge>span{background:var(--bond-color);box-shadow:0 0 8px var(--bond-color);}
  .rift-wisp[data-bond].is-casting{box-shadow:inset 0 2px var(--bond-color),0 0 14px #ffffff70;}
  #rift-bond-effects{position:relative;z-index:2;display:flex;gap:4px;flex:none;min-height:0;flex-wrap:wrap;}
  #rift-bond-effects[hidden]{display:none;}
  .rift-bond-effect{flex:1 1 42%;min-width:0;padding:2px 5px;border:0;border-left:2px solid var(--bond-color);border-radius:3px;background:color-mix(in srgb,var(--bond-color) 7%,transparent);font-size:10px;line-height:12px;color:#d2d1e4;}
  .stage .enemy-stage::after{background:conic-gradient(from 0deg,transparent 0 15%,#b9b6ff33 16% 17%,transparent 18% 48%,#b9b6ff33 49% 50%,transparent 51% 82%,#b9b6ff33 83% 84%,transparent 85%);animation:riftOrbit 32s linear infinite;width:min(200px,65cqh,65cqw);height:min(200px,65cqh,65cqw);max-width:none;max-height:none;}
  .vfx-ability{background:repeating-conic-gradient(var(--vfx-color) 0deg 5deg,transparent 6deg 45deg);}
  @media(prefers-reduced-motion:reduce){.stage .enemy-stage::after{animation:none!important;}.rift-charge>span{transition:none;}}

  @media(max-height:680px){
    .shell:has(#tab-battle.active) .hud{gap:3px;padding:calc(1px + var(--safe-top)) 10px 1px;}
    .shell:has(#tab-battle.active) .hud .chip{height:20px;padding:1px 3px;}
    main.rift-scroll-locked{padding:2px 10px;}
    #tab-battle .stage{padding:3px 8px;gap:1px!important;}
    .rift-heading{display:grid;grid-template-columns:minmax(0,1fr) 160px;gap:4px;height:44px;}
    .stage .depth-label{font-size:14px;line-height:18px;text-align:left;}
    .stage .rift-heading .rift-mode-row{height:44px;min-height:44px;padding:0;}
    .stage .rift-mode-btn{font-size:12px;letter-spacing:0;padding:2px;}
    .farm-depth{display:block;margin:0;font:10px/12px 'IBM Plex Mono',monospace;}
    .stage .battle-row{gap:2px;}
    .stage .hp-wrap{height:24px;}
    .stage .hp-text{font-size:11px;line-height:14px;margin-top:2px;}
    #boss-combat{padding:1px 6px;}
    .boss-net-value{display:none;}
    #rift-party,.rift-wisp{height:54px;}
    .rift-wisp{grid-template-rows:24px 3px 13px 10px;gap:0;padding:1px 3px;}
    #rift-party .wisp-portrait{width:24px;height:24px;}
    .rift-wisp-power{font-size:10px;line-height:10px;}
    .stage .buff-indicator{padding:0 8px;line-height:14px;}
    .stage .stat-box{padding:2px 7px;}
