  nav.tabbar .nav-icon::after{content:'';position:absolute;inset:-1px;border-radius:inherit;pointer-events:none;opacity:0;}
  nav.tabbar .nav-feedback .nav-icon::after{animation:navHalo .3s ease-out;}
