  /* RIFT_COSMETICS_001: SVG/rgba fallbacks also render on WebView 60. */
  .rift-cosmetic-aura{position:absolute;top:0;right:0;bottom:0;left:0;inset:0;width:100%;height:100%;pointer-events:none;z-index:1;}
  .rift-cosmetic-aura .cosmetic-pattern{display:none;}
  [data-rift-theme="ember"] .cosmetic-ember,[data-rift-theme="void"] .cosmetic-void,
  [data-rift-theme="aurora"] .cosmetic-aurora,[data-rift-theme="solar"] .cosmetic-solar,
  [data-rift-theme="radiant"] .cosmetic-radiant{display:inline;}
  #tab-battle .enemy-stage[data-rift-theme]:not([data-rift-theme="default"])::before,
  #tab-battle .enemy-stage[data-rift-theme]:not([data-rift-theme="default"])::after{display:none;}
  #tab-battle .enemy-stage .enemy-glyph{position:relative;z-index:2;}
  .rift-cosmetic-name{position:absolute;left:8px;bottom:4px;z-index:3;max-width:calc(100% - 16px);padding:3px 7px;border:1px solid #61718d;border-radius:6px;background:#10182b;color:#f1edff;font:600 .6875rem/1.4 'Manrope',sans-serif;pointer-events:none;}
  .cosmetic-aurora{animation:riftCosmeticPulse 5s ease-in-out infinite;}
  .cosmetic-radiant{transform-origin:160px 160px;animation:riftCosmeticOrbit 24s linear infinite;}
  @keyframes riftCosmeticPulse{0%,100%{opacity:.65;}50%{opacity:1;}}
  @keyframes riftCosmeticOrbit{to{transform:rotate(360deg);}}
  .theme-card[data-theme-select]{min-height:44px;flex-wrap:wrap;}
